struct RemoteSidecarRuntimeToolState {
    message_source_sequences: Vec<Option<i64>>,
    message_context_sources: Vec<PromptContextSource>,
    active_tool_start_index: usize,
    next_runtime_tool_batch_index: usize,
    runtime_tool_state_compression_count: usize,
    context_budget: ContextBudget,
    compression_enabled: bool,
    /// Active (non-superseded) compression snapshots loaded from / written to the remote workspace DB.
    compression_snapshots: Vec<foco_store::workspace::ContextCompressionSnapshotRecord>,
    /// Last chat-completion provider `input_tokens` in this run (memory only).
    last_chat_completion_input_tokens: Option<u64>,
}

/// Run-scoped tool routing snapshot shared by prompt assembly and execution.
#[derive(Clone, Debug, PartialEq, Eq)]
enum RemoteToolRoute {
    SidecarLocal,
    Broker { method: &'static str },
    McpWorkspace,
    McpLocal,
}

#[derive(Clone)]
struct RemoteToolCatalog {
    tools: Vec<NeutralToolDefinition>,
    routes: HashMap<String, RemoteToolRoute>,
    allowed_names: HashSet<String>,
    workspace_mcp_registry: Arc<McpRegistry>,
    builtin_prompt_tools: Vec<foco_tools::ToolDefinition>,
    memory_prompt_tools: Vec<NeutralToolDefinition>,
    mcp_prompt_tools: Vec<McpToolDefinition>,
}

impl RemoteToolCatalog {
    fn route(&self, name: &str) -> Option<&RemoteToolRoute> {
        self.routes.get(name)
    }

    fn allows(&self, name: &str) -> bool {
        self.allowed_names.contains(name)
    }
}

/// Lightweight remote prompt context: messages plus durable source metadata for snapshot replay.
struct RemotePreparedChatContext {
    provider_request: NeutralChatRequest,
    tool_catalog: Arc<RemoteToolCatalog>,
    session_mode: Option<String>,
    message_source_sequences: Vec<Option<i64>>,
    message_context_sources: Vec<PromptContextSource>,
    active_tool_start_index: usize,
    compression_snapshots: Vec<foco_store::workspace::ContextCompressionSnapshotRecord>,
    context_budget: ContextBudget,
    compression_enabled: bool,
    /// Run-scoped Skill read grants from the same discovery used for `## Skills`.
    /// Not written to runtime bundle, SQLite, or provider request JSON.
    skill_read_root_dirs: Vec<PathBuf>,
    /// Canonical path attachments for this chat (exact `read_file` grants).
    attachment_read_allowlist: Vec<PathBuf>,
}

struct RemoteSidecarHistoryMessages {
    messages: Vec<NeutralChatMessage>,
    /// Database `message.sequence` for each expanded neutral message (assistant tool results share it).
    sequences: Vec<i64>,
}

impl RemoteSidecarRuntimeToolState {
    fn from_prepared(prepared: &RemotePreparedChatContext) -> Self {
        Self {
            message_source_sequences: prepared.message_source_sequences.clone(),
            message_context_sources: prepared.message_context_sources.clone(),
            active_tool_start_index: prepared.active_tool_start_index,
            next_runtime_tool_batch_index: 0,
            runtime_tool_state_compression_count: 0,
            context_budget: prepared.context_budget.clone(),
            compression_enabled: prepared.compression_enabled,
            compression_snapshots: prepared.compression_snapshots.clone(),
            last_chat_completion_input_tokens: None,
        }
    }

    fn for_request(
        state: &RemoteSidecarState,
        request: &NeutralChatRequest,
    ) -> Result<Self, ApiError> {
        // Legacy path for tests that build a bare NeutralChatRequest without DB provenance.
        let tool_catalog = Arc::new(RemoteToolCatalog {
            tools: request.tools.clone(),
            routes: request
                .tools
                .iter()
                .map(|tool| (tool.name.clone(), RemoteToolRoute::SidecarLocal))
                .collect(),
            allowed_names: request.tools.iter().map(|tool| tool.name.clone()).collect(),
            workspace_mcp_registry: Arc::new(McpRegistry::default()),
            builtin_prompt_tools: Vec::new(),
            memory_prompt_tools: Vec::new(),
            mcp_prompt_tools: Vec::new(),
        });
        let prepared = RemotePreparedChatContext {
            provider_request: request.clone(),
            tool_catalog,
            session_mode: None,
            message_source_sequences: vec![None; request.messages.len()],
            message_context_sources: remote_sidecar_initial_context_sources(&request.messages),
            active_tool_start_index: request.messages.len(),
            compression_snapshots: Vec::new(),
            context_budget: remote_sidecar_context_budget_for_request(state, request)?,
            compression_enabled: remote_sidecar_runtime_tool_state_compression_enabled(state),
            skill_read_root_dirs: Vec::new(),
            attachment_read_allowlist: Vec::new(),
        };
        Ok(Self::from_prepared(&prepared))
    }

    fn append_runtime_tool_batch(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        batch_messages: Vec<NeutralChatMessage>,
    ) {
        let batch_index = self.next_runtime_tool_batch_index;
        self.next_runtime_tool_batch_index = self.next_runtime_tool_batch_index.saturating_add(1);
        for message in batch_messages {
            messages.push(message);
            self.message_source_sequences.push(None);
            self.message_context_sources
                .push(PromptContextSource::RuntimeToolState { batch_index });
        }
    }

    fn append_runtime_guard_message(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        action: ReadOnlyToolProgressAction,
    ) {
        if let ReadOnlyToolProgressAction::Warn(message) = action {
            messages.push(neutral_text_message(
                NeutralChatRole::System,
                format!("## Runtime Guard\n\n{}", message.trim()),
            ));
            self.message_source_sequences.push(None);
            self.message_context_sources
                .push(PromptContextSource::RuntimeGuard);
        }
    }

    fn compress_if_needed(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        force: bool,
    ) -> Result<bool, ApiError> {
        compress_runtime_tool_state_messages_if_needed(
            messages,
            &mut self.message_source_sequences,
            &mut self.message_context_sources,
            &mut self.active_tool_start_index,
            &mut self.runtime_tool_state_compression_count,
            &self.context_budget,
            self.compression_enabled,
            force,
        )
    }

    /// Ensure runtime tool-state + optional LLM compression, then pack for the next broker request.
    /// Returns packed messages and compression events for the stream to emit before broker dispatch.
    ///
    /// Same overflow matrix as local `ensure_context_compression`: when
    /// `runtime_tool_state_compression_enabled` is OFF, required-overflow `force=true` is a no-op
    /// and overflow goes to RequiredOverflow LLM only (no stacked tool-state prefix rewrite).
    ///
    /// When `event_tx` is set, events are also pushed live (LLM `start` before the first broker
    /// contextCompression request; `completed` after snapshot insert).
    #[allow(clippy::too_many_arguments)]
    async fn ensure_compression_then_pack(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        state: &RemoteSidecarState,
        run_stream: &RemoteActiveRunStream,
        workspace_id: &str,
        chat_id: &str,
        run_id: &str,
        user_message_id: &str,
        assistant_message_id: &str,
        provider_id: &str,
        model_id: &str,
        event_tx: Option<mpsc::UnboundedSender<RemoteSidecarContextCompressionEventDetail>>,
    ) -> Result<
        (
            Vec<NeutralChatMessage>,
            Vec<RemoteSidecarContextCompressionEventDetail>,
        ),
        ApiError,
    > {
        let events = self
            .ensure_context_compression(
                messages,
                state,
                run_stream,
                workspace_id,
                chat_id,
                run_id,
                user_message_id,
                assistant_message_id,
                provider_id,
                model_id,
                event_tx,
            )
            .await?;
        let packed = pack_neutral_messages(
            messages.clone(),
            &self.message_source_sequences,
            &self.message_context_sources,
            &self.context_budget,
            self.active_tool_start_index,
        )
        .map_err(remote_sidecar_context_overflow_error)?;
        Ok((packed, events))
    }

    #[allow(clippy::too_many_arguments)]
    async fn ensure_context_compression(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        state: &RemoteSidecarState,
        run_stream: &RemoteActiveRunStream,
        workspace_id: &str,
        chat_id: &str,
        run_id: &str,
        user_message_id: &str,
        assistant_message_id: &str,
        provider_id: &str,
        model_id: &str,
        event_tx: Option<mpsc::UnboundedSender<RemoteSidecarContextCompressionEventDetail>>,
    ) -> Result<Vec<RemoteSidecarContextCompressionEventDetail>, ApiError> {
        let mut events = Vec::new();
        let mut runtime_tool_state_compressed = self.compress_runtime_tool_state_with_events(
            messages,
            false,
            provider_id,
            model_id,
            &mut events,
            event_tx.as_ref(),
        )?;

        let mut message_groups = context_message_groups(
            messages,
            &self.message_source_sequences,
            &self.message_context_sources,
            self.active_tool_start_index,
        )?;
        let segments = context_usage_segments(&self.context_budget, &message_groups);
        let total_used_context_tokens = context_usage_segments_total(&segments);
        if should_trigger_normal_llm_context_compression(
            total_used_context_tokens,
            self.last_chat_completion_input_tokens,
            self.context_budget.context_window,
        ) {
            let applied = self
                .ensure_llm_context_compression(
                    messages,
                    &message_groups,
                    &mut events,
                    event_tx.as_ref(),
                    LlmContextCompressionMode::Normal,
                    total_used_context_tokens,
                    state,
                    run_stream,
                    workspace_id,
                    chat_id,
                    run_id,
                    user_message_id,
                    assistant_message_id,
                    provider_id,
                    model_id,
                )
                .await?;
            if applied {
                return Ok(events);
            }
        }

        let mut breakdown = context_token_breakdown(&message_groups);
        if breakdown.required_tokens > self.context_budget.available_message_tokens {
            // force=true only bypasses thresholds when compression_enabled; switch OFF skips here.
            if !runtime_tool_state_compressed {
                runtime_tool_state_compressed |= self.compress_runtime_tool_state_with_events(
                    messages,
                    true,
                    provider_id,
                    model_id,
                    &mut events,
                    event_tx.as_ref(),
                )?;
            }
            message_groups = context_message_groups(
                messages,
                &self.message_source_sequences,
                &self.message_context_sources,
                self.active_tool_start_index,
            )?;
            breakdown = context_token_breakdown(&message_groups);
            if breakdown.required_tokens > self.context_budget.available_message_tokens {
                let _ = self
                    .ensure_llm_context_compression(
                        messages,
                        &message_groups,
                        &mut events,
                        event_tx.as_ref(),
                        LlmContextCompressionMode::RequiredOverflow,
                        total_used_context_tokens,
                        state,
                        run_stream,
                        workspace_id,
                        chat_id,
                        run_id,
                        user_message_id,
                        assistant_message_id,
                        provider_id,
                        model_id,
                    )
                    .await?;
            }
        }

        let _ = runtime_tool_state_compressed;
        Ok(events)
    }

    fn compress_runtime_tool_state_with_events(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        force: bool,
        provider_id: &str,
        model_id: &str,
        events: &mut Vec<RemoteSidecarContextCompressionEventDetail>,
        event_tx: Option<&mpsc::UnboundedSender<RemoteSidecarContextCompressionEventDetail>>,
    ) -> Result<bool, ApiError> {
        let compression_started_at = utc_timestamp();
        let compressed = self.compress_if_needed(messages, force)?;
        if !compressed {
            return Ok(false);
        }
        remote_push_context_compression_event(
            events,
            event_tx,
            RemoteSidecarContextCompressionEventDetail {
                status: "start".to_string(),
                kind: CONTEXT_COMPRESSION_KIND_RUNTIME_TOOL_STATE.to_string(),
                snapshot_id: None,
                original_token_count: None,
                summary_token_count: None,
                started_at: Some(compression_started_at.clone()),
                completed_at: None,
                provider_id: provider_id.to_string(),
                model_id: model_id.to_string(),
            },
        );
        remote_push_context_compression_event(
            events,
            event_tx,
            RemoteSidecarContextCompressionEventDetail {
                status: "completed".to_string(),
                kind: CONTEXT_COMPRESSION_KIND_RUNTIME_TOOL_STATE.to_string(),
                snapshot_id: None,
                original_token_count: None,
                summary_token_count: None,
                started_at: Some(compression_started_at),
                completed_at: Some(utc_timestamp()),
                provider_id: provider_id.to_string(),
                model_id: model_id.to_string(),
            },
        );
        Ok(true)
    }

    #[allow(clippy::too_many_arguments)]
    async fn ensure_llm_context_compression(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        message_groups: &[crate::ContextMessageGroup],
        events: &mut Vec<RemoteSidecarContextCompressionEventDetail>,
        event_tx: Option<&mpsc::UnboundedSender<RemoteSidecarContextCompressionEventDetail>>,
        mode: LlmContextCompressionMode,
        local_total_used_tokens: u64,
        state: &RemoteSidecarState,
        run_stream: &RemoteActiveRunStream,
        workspace_id: &str,
        chat_id: &str,
        run_id: &str,
        user_message_id: &str,
        assistant_message_id: &str,
        provider_id: &str,
        model_id: &str,
    ) -> Result<bool, ApiError> {
        let Some(plan) = plan_llm_context_compression(
            messages,
            &self.message_source_sequences,
            &self.message_context_sources,
            &self.compression_snapshots,
            message_groups,
            self.context_budget.available_message_tokens,
            mode,
        )?
        else {
            return Ok(false);
        };
        let covered_indices = plan.covered_message_indices;
        let original_tokens = plan.original_tokens;
        let checkpoint_messages = plan.checkpoint_messages;
        let covered_snapshot_ids = plan.covered_snapshot_ids;
        let covered_sequences = plan.covered_sequences;
        let compression_started_at = utc_timestamp();
        // Live start before the first broker contextCompression request.
        remote_push_context_compression_event(
            events,
            event_tx,
            RemoteSidecarContextCompressionEventDetail {
                status: "start".to_string(),
                kind: CONTEXT_COMPRESSION_KIND_LLM.to_string(),
                snapshot_id: None,
                original_token_count: Some(i64::try_from(original_tokens).map_err(|_| {
                    ApiError::internal("context compression original token count exceeds i64")
                })?),
                summary_token_count: None,
                started_at: Some(compression_started_at.clone()),
                completed_at: None,
                provider_id: provider_id.to_string(),
                model_id: model_id.to_string(),
            },
        );
        let compression_start_event_index = events.len() - 1;

        let (summary, resolved_provider_id) =
            match remote_sidecar_run_broker_context_compression_summary(
                state,
                Some(run_stream),
                workspace_id,
                chat_id,
                run_id,
                user_message_id,
                assistant_message_id,
                provider_id,
                model_id,
                self.context_budget.context_window,
                &checkpoint_messages,
            )
            .await
            {
                RemoteSidecarContextCompressionOutcome::Succeeded {
                    summary,
                    provider_id,
                    ..
                } => (summary, provider_id),
                RemoteSidecarContextCompressionOutcome::Cancelled => {
                    events.truncate(compression_start_event_index);
                    return Err(ApiError::bad_request(
                        "context compression summary was cancelled",
                    ));
                }
                RemoteSidecarContextCompressionOutcome::Failed { message } => {
                    events.truncate(compression_start_event_index);
                    return Err(ApiError::bad_request(
                        remote_sidecar_context_compression_failure_message(
                            RemoteSidecarContextCompressionFailureKind::SummaryGeneration,
                            &message,
                        ),
                    ));
                }
            };
        events[compression_start_event_index].provider_id = resolved_provider_id.clone();

        if !context_compression_summary_has_benefit(&summary, original_tokens) {
            events.truncate(compression_start_event_index);
            return Ok(false);
        }
        let summary_token_count = estimate_text_tokens(&summary);
        let workspace_path = PathBuf::from(&state.workspace_path);
        let (_mcp_registry, hook_runtime, global_hooks, global_config, retry_count) =
            match remote_sidecar_hook_environment(state, None).await {
                Ok(environment) => environment,
                Err(error) => {
                    events.truncate(compression_start_event_index);
                    run_stream.push_hook_notifications(vec![HookNotification {
                        event: "PreCompact".to_string(),
                        level: "error".to_string(),
                        message: error.clone(),
                    }]);
                    return Err(ApiError::internal(error));
                }
            };
        let pre_summary = hook_runtime
            .run_hooks(HookRunRequest {
                global_config: &global_hooks,
                api_audit_save_details: api_audit_save_details(&global_config),
                workspace_id,
                workspace_path: &workspace_path,
                event: "PreCompact",
                match_value: None,
                chat_id: Some(chat_id),
                run_id: Some(run_id),
                session_id: Some(chat_id),
                tool_call_id: None,
                model_id: Some(model_id),
                provider_id: Some(resolved_provider_id.as_str()),
                provider_config: None,
                llm_request_retry_count: retry_count,
                permission_mode: None,
                payload: json!({
                    "kind": CONTEXT_COMPRESSION_KIND_LLM,
                    "coveredSequences": covered_sequences,
                    "originalTokenCount": original_tokens,
                    "summaryTokenCount": summary_token_count,
                    "summary": summary.clone(),
                }),
            })
            .await;
        run_stream.push_hook_notifications(pre_summary.hook_messages("PreCompact"));
        self.append_hook_context(messages, &pre_summary.additional_context);
        if pre_summary.first_block_reason().is_some() {
            events.truncate(compression_start_event_index);
            return Ok(false);
        }

        let metadata = {
            let mut metadata = json!({
                "kind": CONTEXT_COMPRESSION_KIND_LLM,
                "coveredSequences": covered_sequences,
                "coveredSnapshotIds": covered_snapshot_ids,
                "supersededSnapshotIds": covered_snapshot_ids,
                "triggerTokens": llm_context_compression_trigger_tokens(self.context_budget.context_window),
                "availableMessageTokens": self.context_budget.available_message_tokens,
            });
            if matches!(mode, LlmContextCompressionMode::Normal)
                && let Some(trigger_source) = llm_context_compression_trigger_source(
                    local_total_used_tokens,
                    self.last_chat_completion_input_tokens,
                    self.context_budget.context_window,
                )
            {
                metadata["triggerSource"] = json!(trigger_source);
            }
            metadata
        };
        let prepared = match prepare_context_compression_snapshot(
            chat_id,
            run_id,
            messages,
            &self.message_source_sequences,
            &self.message_context_sources,
            self.active_tool_start_index,
            &self.compression_snapshots,
            &self.context_budget,
            &covered_indices,
            summary,
            original_tokens,
            summary_token_count,
            metadata,
        ) {
            Ok(prepared) => prepared,
            Err(error) => {
                events.truncate(compression_start_event_index);
                return Err(error);
            }
        };
        if let Err(error) = (|| {
            let mut database = WorkspaceDatabase::open_or_create(sidecar_workspace_path(state))
                .map_err(ApiError::from_workspace_error)?;
            insert_context_compression_snapshot_record(&mut database, &prepared)
        })() {
            events.truncate(compression_start_event_index);
            return Err(error);
        }

        *messages = prepared.replaced.messages;
        self.message_source_sequences = prepared.replaced.message_source_sequences;
        self.message_context_sources = prepared.replaced.message_context_sources;
        self.active_tool_start_index = prepared.replaced.active_tool_start_index;
        self.compression_snapshots.push(prepared.snapshot.clone());
        // Full LLM checkpoint covers prior RuntimeToolState snapshots; allow a new 80% local cycle.
        self.runtime_tool_state_compression_count = 0;

        remote_push_context_compression_event(
            events,
            event_tx,
            RemoteSidecarContextCompressionEventDetail {
                status: "completed".to_string(),
                kind: CONTEXT_COMPRESSION_KIND_LLM.to_string(),
                snapshot_id: Some(prepared.snapshot.id.clone()),
                original_token_count: Some(prepared.snapshot.original_token_count),
                summary_token_count: Some(prepared.snapshot.summary_token_count),
                started_at: Some(compression_started_at),
                completed_at: Some(utc_timestamp()),
                provider_id: resolved_provider_id.clone(),
                model_id: model_id.to_string(),
            },
        );

        let post_summary = hook_runtime
            .run_hooks(HookRunRequest {
                global_config: &global_hooks,
                api_audit_save_details: api_audit_save_details(&global_config),
                workspace_id,
                workspace_path: &workspace_path,
                event: "PostCompact",
                match_value: None,
                chat_id: Some(chat_id),
                run_id: Some(run_id),
                session_id: Some(chat_id),
                tool_call_id: None,
                model_id: Some(model_id),
                provider_id: Some(resolved_provider_id.as_str()),
                provider_config: None,
                llm_request_retry_count: retry_count,
                permission_mode: None,
                payload: json!({
                    "kind": CONTEXT_COMPRESSION_KIND_LLM,
                    "snapshotId": prepared.snapshot.id,
                }),
            })
            .await;
        run_stream.push_hook_notifications(post_summary.hook_messages("PostCompact"));
        self.append_hook_context(messages, &post_summary.additional_context);
        Ok(true)
    }

    fn append_hook_context(&mut self, messages: &mut Vec<NeutralChatMessage>, contexts: &[String]) {
        let message_count_before = messages.len();
        append_hook_context_messages(
            messages,
            &mut self.message_source_sequences,
            &mut self.message_context_sources,
            contexts,
        );
        if self.active_tool_start_index == message_count_before {
            self.active_tool_start_index = messages.len();
        }
    }

    fn recover_after_round_cap(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
        tool_calls: Vec<NeutralToolCall>,
        assistant_text: String,
        assistant_reasoning: Option<String>,
    ) -> Result<bool, ApiError> {
        append_pending_tool_state_messages(
            messages,
            &mut self.message_source_sequences,
            &mut self.message_context_sources,
            &mut self.next_runtime_tool_batch_index,
            tool_calls,
            assistant_text,
            assistant_reasoning,
        );
        compress_all_runtime_tool_state_messages(
            messages,
            &mut self.message_source_sequences,
            &mut self.message_context_sources,
            &mut self.active_tool_start_index,
        )
    }

    fn packed_messages_for_request(
        &mut self,
        messages: &mut Vec<NeutralChatMessage>,
    ) -> Result<Vec<NeutralChatMessage>, ApiError> {
        // Synchronous path used by unit tests; production chat loop uses ensure_compression_then_pack.
        // compress_if_needed(..., true) still respects compression_enabled (force cannot bypass switch).
        self.compress_if_needed(messages, false)?;
        match pack_neutral_messages(
            messages.clone(),
            &self.message_source_sequences,
            &self.message_context_sources,
            &self.context_budget,
            self.active_tool_start_index,
        ) {
            Ok(messages) => Ok(messages),
            Err(first_error) => {
                if self.compress_if_needed(messages, true)? {
                    return pack_neutral_messages(
                        messages.clone(),
                        &self.message_source_sequences,
                        &self.message_context_sources,
                        &self.context_budget,
                        self.active_tool_start_index,
                    )
                    .map_err(remote_sidecar_context_overflow_error);
                }
                Err(remote_sidecar_context_overflow_error(first_error))
            }
        }
    }
}

fn remote_sidecar_runtime_tool_state_compression_enabled(state: &RemoteSidecarState) -> bool {
    state
        .runtime_config
        .lock()
        .ok()
        .and_then(|config| config.clone())
        .is_some_and(|bundle| bundle.payload.app.runtime_tool_state_compression_enabled)
}

fn remote_sidecar_context_budget_for_request(
    state: &RemoteSidecarState,
    request: &NeutralChatRequest,
) -> Result<ContextBudget, ApiError> {
    let bundle = state
        .runtime_config
        .lock()
        .ok()
        .and_then(|config| config.clone());
    bundle
        .as_ref()
        .and_then(|bundle| {
            bundle
                .payload
                .models
                .iter()
                .find(|model| model.id == request.model_id)
        })
        .and_then(|model| model.limits.as_ref())
        .map(|limits| {
            calculate_context_budget(
                limits.context_window,
                limits.max_output_tokens,
                0,
                estimate_tool_schema_tokens(&request.tools),
            )
            .map_err(|source| ApiError::bad_request(source.to_string()))
        })
        .transpose()?
        .map(Ok)
        .unwrap_or(Ok(ContextBudget {
            context_window: u64::MAX,
            max_output_tokens: 0,
            system_prompt_tokens: 0,
            tool_schema_tokens: 0,
            safety_tokens: 0,
            available_message_tokens: u64::MAX,
        }))
}

fn remote_sidecar_initial_context_sources(
    messages: &[NeutralChatMessage],
) -> Vec<PromptContextSource> {
    let current_user_index = messages
        .iter()
        .rposition(|message| message.role == NeutralChatRole::User);
    let mut next_sequence = 0_i64;
    let mut active_tool_sequence = None;

    messages
        .iter()
        .enumerate()
        .map(|(index, message)| {
            if message.role == NeutralChatRole::System {
                active_tool_sequence = None;
                return PromptContextSource::ReservedPrompt;
            }
            if Some(index) == current_user_index {
                let sequence = next_sequence;
                next_sequence = next_sequence.saturating_add(1);
                active_tool_sequence = None;
                return PromptContextSource::CurrentUser { sequence };
            }
            if message.role == NeutralChatRole::Tool {
                let sequence = active_tool_sequence.unwrap_or_else(|| {
                    let sequence = next_sequence;
                    next_sequence = next_sequence.saturating_add(1);
                    active_tool_sequence = Some(sequence);
                    sequence
                });
                return PromptContextSource::StoredMessage { sequence };
            }

            let sequence = next_sequence;
            next_sequence = next_sequence.saturating_add(1);
            active_tool_sequence = (message.role == NeutralChatRole::Assistant
                && !message.tool_calls.is_empty())
            .then_some(sequence);
            PromptContextSource::StoredMessage { sequence }
        })
        .collect()
}

fn remote_sidecar_current_turn_output(accumulated: &str, turn_start: usize) -> String {
    accumulated[turn_start..].to_string()
}

fn remote_sidecar_flush_open_content_parts(
    content_parts_prefix: &mut Vec<Value>,
    text: &str,
    reasoning: &str,
    flushed_text_len: &mut usize,
    flushed_reasoning_len: &mut usize,
) {
    let unflushed_reasoning = reasoning.get(*flushed_reasoning_len..).unwrap_or_default();
    if !unflushed_reasoning.is_empty() {
        content_parts_prefix.push(json!({
            "type": "reasoning",
            "text": unflushed_reasoning,
        }));
    }
    let unflushed_text = text.get(*flushed_text_len..).unwrap_or_default();
    if !unflushed_text.is_empty() {
        content_parts_prefix.push(json!({
            "type": "text",
            "text": unflushed_text,
        }));
    }
    *flushed_text_len = text.len();
    *flushed_reasoning_len = reasoning.len();
}

fn remote_sidecar_append_reasoning_loop_recovery_to_request(
    messages: &mut Vec<NeutralChatMessage>,
    runtime_tool_state: &mut RemoteSidecarRuntimeToolState,
    turn_text: &str,
    turn_reasoning: &str,
) {
    if !turn_text.trim().is_empty() || !turn_reasoning.trim().is_empty() {
        messages.push(NeutralChatMessage {
            role: NeutralChatRole::Assistant,
            content: turn_text.to_string(),
            attachments: Vec::new(),
            reasoning: (!turn_reasoning.is_empty()).then(|| turn_reasoning.to_string()),
            tool_calls: Vec::new(),
            tool_call_id: None,
            tool_name: None,
        });
        runtime_tool_state.message_source_sequences.push(None);
        runtime_tool_state
            .message_context_sources
            .push(PromptContextSource::RuntimeAssistant);
    }
    messages.push(NeutralChatMessage {
        role: NeutralChatRole::User,
        content: REASONING_LOOP_RECOVERY_USER_TEXT.to_string(),
        attachments: Vec::new(),
        reasoning: None,
        tool_calls: Vec::new(),
        tool_call_id: None,
        tool_name: None,
    });
    runtime_tool_state.message_source_sequences.push(None);
    runtime_tool_state
        .message_context_sources
        .push(PromptContextSource::Guidance);
}

fn remote_sidecar_tool_round_cap_error(max_tool_rounds: usize) -> String {
    format!(
        "agent run exceeded {max_tool_rounds} tool continuation rounds and had no runtime tool state to compress"
    )
}

