#[derive(Debug)]
struct RemoteSidecarCleanupFlight {
    result_tx: watch::Sender<Option<Arc<RemoteSidecarCleanupOutcome>>>,
}

impl RemoteSidecarCleanupFlight {
    fn new() -> Self {
        let (result_tx, _) = watch::channel(None);
        Self { result_tx }
    }

    fn subscribe(&self) -> watch::Receiver<Option<Arc<RemoteSidecarCleanupOutcome>>> {
        self.result_tx.subscribe()
    }

    fn publish(&self, outcome: Arc<RemoteSidecarCleanupOutcome>) {
        self.result_tx.send_replace(Some(outcome));
    }
}

#[derive(Debug)]
enum RemoteSidecarCleanupFlightJoin {
    Leader(RemoteSidecarCleanupFlightLeader),
    Waiter(RemoteSidecarCleanupFlightWaiter),
}

#[derive(Debug)]
struct RemoteSidecarCleanupFlightLeader {
    flights: Arc<Mutex<HashMap<RemoteSidecarCleanupKey, Arc<RemoteSidecarCleanupFlight>>>>,
    key: RemoteSidecarCleanupKey,
    flight: Arc<RemoteSidecarCleanupFlight>,
    completed: bool,
}

impl RemoteSidecarCleanupFlightLeader {
    fn complete(mut self, outcome: Arc<RemoteSidecarCleanupOutcome>) {
        self.flight.publish(outcome);
        self.completed = true;
        release_remote_sidecar_cleanup_flight(&self.flights, &self.key, &self.flight);
    }
}

impl Drop for RemoteSidecarCleanupFlightLeader {
    fn drop(&mut self) {
        if self.completed {
            return;
        }
        tracing::warn!(
            server_id = %self.key.server_id,
            managed_install_version = %self.key.managed_install_version,
            "managed remote sidecar cleanup leader ended before publishing a result"
        );
        self.flight
            .publish(Arc::new(RemoteSidecarCleanupOutcome::LeaderCancelled));
        release_remote_sidecar_cleanup_flight(&self.flights, &self.key, &self.flight);
    }
}

#[derive(Debug)]
struct RemoteSidecarCleanupFlightWaiter {
    flights: Arc<Mutex<HashMap<RemoteSidecarCleanupKey, Arc<RemoteSidecarCleanupFlight>>>>,
    key: RemoteSidecarCleanupKey,
    flight: Arc<RemoteSidecarCleanupFlight>,
    result_rx: watch::Receiver<Option<Arc<RemoteSidecarCleanupOutcome>>>,
}

impl RemoteSidecarCleanupFlightWaiter {
    async fn wait(mut self) -> Arc<RemoteSidecarCleanupOutcome> {
        loop {
            if let Some(outcome) = self.result_rx.borrow_and_update().clone() {
                return outcome;
            }
            if self.result_rx.changed().await.is_err() {
                return Arc::new(RemoteSidecarCleanupOutcome::LeaderCancelled);
            }
        }
    }
}

impl Drop for RemoteSidecarCleanupFlightWaiter {
    fn drop(&mut self) {
        release_remote_sidecar_cleanup_flight(&self.flights, &self.key, &self.flight);
    }
}

impl RemoteSidecarCleanupSingleflight {
    fn join(&self, key: RemoteSidecarCleanupKey) -> RemoteSidecarCleanupFlightJoin {
        let mut flights = lock_remote_sidecar_cleanup_flights(&self.flights);
        if let Some(flight) = flights.get(&key) {
            return RemoteSidecarCleanupFlightJoin::Waiter(RemoteSidecarCleanupFlightWaiter {
                flights: self.flights.clone(),
                key,
                flight: flight.clone(),
                result_rx: flight.subscribe(),
            });
        }

        let flight = Arc::new(RemoteSidecarCleanupFlight::new());
        flights.insert(key.clone(), flight.clone());
        RemoteSidecarCleanupFlightJoin::Leader(RemoteSidecarCleanupFlightLeader {
            flights: self.flights.clone(),
            key,
            flight,
            completed: false,
        })
    }
}

fn lock_remote_sidecar_cleanup_flights(
    flights: &Arc<Mutex<HashMap<RemoteSidecarCleanupKey, Arc<RemoteSidecarCleanupFlight>>>>,
) -> std::sync::MutexGuard<'_, HashMap<RemoteSidecarCleanupKey, Arc<RemoteSidecarCleanupFlight>>> {
    match flights.lock() {
        Ok(flights) => flights,
        Err(poisoned) => {
            tracing::warn!(
                "managed remote sidecar cleanup singleflight lock was poisoned; recovering state"
            );
            poisoned.into_inner()
        }
    }
}

fn release_remote_sidecar_cleanup_flight(
    flights: &Arc<Mutex<HashMap<RemoteSidecarCleanupKey, Arc<RemoteSidecarCleanupFlight>>>>,
    key: &RemoteSidecarCleanupKey,
    flight: &Arc<RemoteSidecarCleanupFlight>,
) {
    let mut flights = lock_remote_sidecar_cleanup_flights(flights);
    let should_remove = flights
        .get(key)
        .is_some_and(|existing| Arc::ptr_eq(existing, flight) && Arc::strong_count(existing) == 2);
    if should_remove {
        flights.remove(key);
    }
}

#[derive(Clone, Debug, Default)]
pub(crate) struct RemoteWorkspaceManager {
    sessions: Arc<Mutex<HashMap<String, Arc<RemoteWorkspaceSession>>>>,
    statuses: Arc<Mutex<HashMap<String, RemoteSessionStatus>>>,
    // ponytail: process-local keyed mutex; remote lockfile later if multiple Foco processes must coordinate.
    sidecar_install_locks: Arc<Mutex<HashMap<String, Arc<AsyncMutex<()>>>>>,
    sidecar_cleanup_singleflight: RemoteSidecarCleanupSingleflight,
}

impl RemoteWorkspaceManager {
    pub(crate) async fn connect_workspace(
        &self,
        state: AppState,
        server_id: &str,
        workspace_id: &str,
    ) -> Result<RemoteWorkspaceSessionSummary, ApiError> {
        match self
            .connect_workspace_inner(state, server_id, workspace_id)
            .await
        {
            Ok(summary) => Ok(summary),
            Err(error) => {
                let message = error.message().to_string();
                let state = if is_auth_error_message(&message) {
                    RemoteConnectionState::FailedAuth
                } else {
                    RemoteConnectionState::Offline
                };
                let _ =
                    self.set_status(server_id, Some(workspace_id), state, Some(message.clone()));
                let _ = self.set_status(server_id, None, state, Some(message));
                Err(error)
            }
        }
    }

    pub(crate) async fn ensure_server_sidecar(
        &self,
        state: AppState,
        server_id: &str,
    ) -> Result<(), ApiError> {
        match self.ensure_server_sidecar_inner(&state, server_id).await {
            Ok(()) => Ok(()),
            Err(error) => {
                let message = error.message().to_string();
                let state = if is_auth_error_message(&message) {
                    RemoteConnectionState::FailedAuth
                } else {
                    RemoteConnectionState::Offline
                };
                let _ = self.set_status(server_id, None, state, Some(message));
                Err(error)
            }
        }
    }

    async fn ensure_server_sidecar_inner(
        &self,
        state: &AppState,
        server_id: &str,
    ) -> Result<(), ApiError> {
        let config = config_snapshot(state)?;
        let server = config
            .remote_servers
            .iter()
            .find(|server| server.id == server_id)
            .cloned()
            .ok_or_else(|| remote_error(server_id, None, "remote server was not found"))?;
        self.set_status(server_id, None, RemoteConnectionState::Checking, None)?;
        let target = detect_or_cached_target(&server, server_id, None).await?;
        self.set_status(server_id, None, RemoteConnectionState::Installing, None)?;
        ensure_sidecar_command(state, &server, server_id, None, &target).await?;
        self.set_status(server_id, None, RemoteConnectionState::Ready, None)?;
        Ok(())
    }

    fn set_status(
        &self,
        server_id: &str,
        workspace_id: Option<&str>,
        state: RemoteConnectionState,
        last_error: Option<String>,
    ) -> Result<(), ApiError> {
        let key = status_key(server_id, workspace_id);
        let mut statuses = self
            .statuses
            .lock()
            .map_err(|_| ApiError::internal("remote workspace status lock is poisoned"))?;
        statuses.insert(key, RemoteSessionStatus::new(state, last_error));
        Ok(())
    }

    fn get_status(
        &self,
        server_id: &str,
        workspace_id: Option<&str>,
    ) -> Result<Option<RemoteSessionStatus>, ApiError> {
        let statuses = self
            .statuses
            .lock()
            .map_err(|_| ApiError::internal("remote workspace status lock is poisoned"))?;
        Ok(statuses.get(&status_key(server_id, workspace_id)).cloned())
    }

    fn sidecar_install_lock(&self, key: &str) -> Result<Arc<AsyncMutex<()>>, ApiError> {
        let mut locks = self
            .sidecar_install_locks
            .lock()
            .map_err(|_| ApiError::internal("remote sidecar install lock map is poisoned"))?;
        Ok(locks
            .entry(key.to_string())
            .or_insert_with(|| Arc::new(AsyncMutex::new(())))
            .clone())
    }

    fn remove_sidecar_install_lock(
        &self,
        key: &str,
        lock: &Arc<AsyncMutex<()>>,
    ) -> Result<(), ApiError> {
        let mut locks = self
            .sidecar_install_locks
            .lock()
            .map_err(|_| ApiError::internal("remote sidecar install lock map is poisoned"))?;
        let should_remove = locks.get(key).is_some_and(|existing| {
            Arc::ptr_eq(existing, lock) && Arc::strong_count(existing) == 2
        });
        if should_remove {
            locks.remove(key);
        }
        Ok(())
    }

    async fn connect_workspace_inner(
        &self,
        state: AppState,
        server_id: &str,
        workspace_id: &str,
    ) -> Result<RemoteWorkspaceSessionSummary, ApiError> {
        let config = config_snapshot(&state)?;
        let server = config
            .remote_servers
            .iter()
            .find(|server| server.id == server_id)
            .cloned()
            .ok_or_else(|| {
                remote_error(server_id, Some(workspace_id), "remote server was not found")
            })?;
        let workspace = workspace_by_id(&config, workspace_id)?.clone();
        let remote_path = workspace_remote_path(&workspace, server_id)?;
        let target = detect_or_cached_target(&server, server_id, Some(workspace_id)).await?;
        let expected_identity =
            expected_remote_sidecar_identity(&server, &target, server_id, Some(workspace_id))
                .await?;
        let key = session_key(server_id, workspace_id);
        let replacement_lock_key = session_replacement_lock_key(server_id, workspace_id);
        let replacement_lock = self.sidecar_install_lock(&replacement_lock_key)?;
        let result = {
            let _replacement_guard = replacement_lock.lock().await;
            self.connect_workspace_with_expected_identity(
                state,
                &config,
                &server,
                server_id,
                workspace_id,
                &remote_path,
                &key,
                &target,
                &expected_identity,
            )
            .await
        };
        self.remove_sidecar_install_lock(&replacement_lock_key, &replacement_lock)?;
        result
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "connection setup keeps all validated session inputs explicit"
    )]
    async fn connect_workspace_with_expected_identity(
        &self,
        state: AppState,
        config: &foco_store::config::GlobalConfig,
        server: &RemoteServerProfile,
        server_id: &str,
        workspace_id: &str,
        remote_path: &str,
        key: &str,
        target: &str,
        expected_identity: &RemoteSidecarIdentity,
    ) -> Result<RemoteWorkspaceSessionSummary, ApiError> {
        self.set_status(
            server_id,
            Some(workspace_id),
            RemoteConnectionState::Checking,
            None,
        )?;
        self.set_status(server_id, None, RemoteConnectionState::Checking, None)?;

        let stale_session = {
            let mut sessions = self
                .sessions
                .lock()
                .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
            match sessions.get(key) {
                Some(existing)
                    if existing.matches_expected_identity(
                        server_id,
                        workspace_id,
                        expected_identity,
                    ) =>
                {
                    self.set_status(
                        server_id,
                        Some(workspace_id),
                        RemoteConnectionState::Ready,
                        None,
                    )?;
                    self.set_status(server_id, None, RemoteConnectionState::Ready, None)?;
                    return Ok(existing.summary());
                }
                Some(_) => sessions.remove(key),
                None => None,
            }
        };
        if let Some(session) = stale_session {
            // The stale tunnel must be gone before an upgrade can install and launch a
            // replacement. Keep the session-map lock out of this async teardown.
            session.stop().await;
            // stop() aborts the control task (skips control-loop cleanup); clear any
            // main-process Provider WebSocket sessions for this workspace before reconnect.
            state
                .openai_resp_ws_sessions
                .invalidate_workspace(workspace_id)
                .await;
        }

        self.set_status(
            server_id,
            Some(workspace_id),
            RemoteConnectionState::Installing,
            None,
        )?;
        self.set_status(server_id, None, RemoteConnectionState::Installing, None)?;
        let sidecar_command =
            ensure_sidecar_command(&state, server, server_id, Some(workspace_id), target).await?;
        if sidecar_command.identity != *expected_identity {
            return Err(remote_error(
                server_id,
                Some(workspace_id),
                "remote sidecar identity changed while preparing the upgrade; retry the connection",
            ));
        }

        self.set_status(
            server_id,
            Some(workspace_id),
            RemoteConnectionState::Connecting,
            None,
        )?;
        let token = random_token()?;
        let session_file = ensure_remote_session_file(
            server,
            server_id,
            workspace_id,
            remote_path,
            target,
            &token,
        )
        .await?;
        stop_stale_remote_sidecars(server, server_id, workspace_id, remote_path).await?;
        self.set_status(
            server_id,
            Some(workspace_id),
            RemoteConnectionState::Starting,
            None,
        )?;
        // Long-lived SSH/sidecar/forward resources must be aborted explicitly on any
        // mid-connect failure; russh Handle Drop does not send Disconnect.
        let mut partial = PartialRemoteConnect::with_ssh(
            open_remote_ssh_session(server, server_id, Some(workspace_id)).await?,
        );
        let finish: Result<
            (
                RemoteSidecarBootstrap,
                u16,
                Arc<Mutex<RemoteSessionStatus>>,
                Arc<Mutex<Vec<RemoteActiveRunSummary>>>,
            ),
            ApiError,
        > = async {
            let sidecar = launch_remote_sidecar(
                partial.ssh_ref(),
                server_id,
                workspace_id,
                remote_path,
                target,
                &token,
                &sidecar_command.command,
                &session_file,
            )
            .await?;
            partial.sidecar = Some(sidecar);
            let bootstrap = read_bootstrap(
                partial.sidecar.as_mut().expect("sidecar set after launch"),
                server_id,
                workspace_id,
            )
            .await?;
            validate_bootstrap(
                &bootstrap,
                server_id,
                workspace_id,
                &token,
                &sidecar_command.identity,
            )?;
            self.set_status(
                server_id,
                Some(workspace_id),
                RemoteConnectionState::Tunneling,
                None,
            )?;
            let status = Arc::new(Mutex::new(RemoteSessionStatus::new(
                RemoteConnectionState::BrokerConnecting,
                None,
            )));
            let (local_port, forward_stop, forward_task) = start_direct_tcpip_forward(
                Arc::clone(partial.ssh_ref()),
                bootstrap.port,
                server_id,
                workspace_id,
                status.clone(),
            )
            .await?;
            partial.forward_stop = Some(forward_stop);
            partial.forward_task = Some(forward_task);
            let bundle = build_sidecar_runtime_config_bundle(
                &state.user_profile_dir,
                config,
                Utc::now().timestamp_millis().max(0) as u64,
            )?;
            let active_runs = Arc::new(Mutex::new(Vec::new()));
            self.set_status(
                server_id,
                Some(workspace_id),
                RemoteConnectionState::BrokerConnecting,
                None,
            )?;
            self.set_status(
                server_id,
                None,
                RemoteConnectionState::BrokerConnecting,
                None,
            )?;
            let control_task = connect_control_ws(
                state.clone(),
                local_port,
                &token,
                bundle,
                server_id,
                workspace_id,
                active_runs.clone(),
                status.clone(),
            )
            .await?;
            partial.control_task = Some(control_task);
            Ok((bootstrap, local_port, status, active_runs))
        }
        .await;

        let (bootstrap, local_port, status, active_runs) = match finish {
            Ok(ok) => ok,
            Err(err) => {
                partial.abort().await;
                let _ = self.set_status(
                    server_id,
                    Some(workspace_id),
                    RemoteConnectionState::Offline,
                    Some(err.message().to_string()),
                );
                return Err(err);
            }
        };

        let (ssh_session, sidecar, forward_stop, forward_task, control_task) =
            partial.take_into_session();
        let session = Arc::new(RemoteWorkspaceSession {
            server_id: server_id.to_string(),
            workspace_id: workspace_id.to_string(),
            remote_path: remote_path.to_string(),
            sidecar_identity: sidecar_command.identity.clone(),
            target: target.to_string(),
            local_port,
            remote_port: bootstrap.port,
            token: token.clone(),
            started_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            ssh: AsyncMutex::new(Some(ssh_session)),
            sidecar: AsyncMutex::new(Some(sidecar)),
            forward_stop: AsyncMutex::new(Some(forward_stop)),
            forward_task: AsyncMutex::new(Some(forward_task)),
            control_task: AsyncMutex::new(Some(control_task)),
            health_task: AsyncMutex::new(Some(start_sidecar_health_ping(
                local_port,
                token.clone(),
                status.clone(),
            ))),
            status,
            active_runs,
        });
        self.set_status(
            server_id,
            Some(workspace_id),
            RemoteConnectionState::Ready,
            None,
        )?;
        self.set_status(server_id, None, RemoteConnectionState::Ready, None)?;

        // Register the session before best-effort version cleanup so concurrent connect
        // short-circuits on an actual session map entry (not Ready status alone). Keep the
        // std MutexGuard off the await: insert under a short lock, then cleanup over SSH.
        let summary = session.summary();
        {
            let mut sessions = self
                .sessions
                .lock()
                .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
            sessions.insert(key.to_string(), session);
        }

        // The cache is diagnostics only. Refresh it only after this session's bootstrap
        // identity and broker are both verified, never while a binary is merely installed.
        if let Err(error) = update_verified_sidecar_cache(
            &state,
            server_id,
            &sidecar_command.identity,
            sidecar_command.managed_install_version.is_some(),
        )
        .await
        {
            tracing::warn!(
                server_id = %server_id,
                workspace_id = %workspace_id,
                version = %sidecar_command.identity.version,
                error = %error.message(),
                "failed to persist verified remote sidecar diagnostic cache"
            );
        }

        // Best-effort: after bootstrap identity + control broker succeed, prune older
        // Foco-managed sidecar version dirs. Custom focoCommand is skipped. Failures never
        // downgrade a successful Ready session.
        self.maybe_cleanup_stale_managed_remote_sidecar_versions(
            server,
            server_id,
            workspace_id,
            &sidecar_command,
        )
        .await;

        Ok(summary)
    }

    pub(crate) async fn disconnect_workspace(
        &self,
        server_id: &str,
        workspace_id: &str,
    ) -> Result<bool, ApiError> {
        let session = {
            let mut sessions = self
                .sessions
                .lock()
                .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
            sessions.remove(&session_key(server_id, workspace_id))
        };
        if let Some(session) = session {
            session.stop().await;
            self.set_status(
                server_id,
                Some(workspace_id),
                RemoteConnectionState::Disconnected,
                None,
            )?;
            Ok(true)
        } else {
            self.set_status(
                server_id,
                Some(workspace_id),
                RemoteConnectionState::Disconnected,
                None,
            )?;
            Ok(false)
        }
    }

    pub(crate) async fn disconnect_server(&self, server_id: &str) -> Result<Vec<String>, ApiError> {
        let removed = {
            let mut sessions = self
                .sessions
                .lock()
                .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
            let keys = sessions
                .keys()
                .filter(|key| key.starts_with(&format!("{server_id}:")))
                .cloned()
                .collect::<Vec<_>>();
            keys.into_iter()
                .filter_map(|key| sessions.remove(&key))
                .collect::<Vec<_>>()
        };
        let mut workspace_ids = Vec::with_capacity(removed.len());
        for session in removed {
            workspace_ids.push(session.workspace_id.clone());
            self.set_status(
                &session.server_id,
                Some(&session.workspace_id),
                RemoteConnectionState::Disconnected,
                None,
            )?;
            session.stop().await;
        }
        self.set_status(server_id, None, RemoteConnectionState::Disconnected, None)?;
        Ok(workspace_ids)
    }

    pub(crate) async fn disconnect_all(&self) -> Result<Vec<String>, ApiError> {
        let removed = {
            let mut sessions = self
                .sessions
                .lock()
                .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
            sessions
                .drain()
                .map(|(_, session)| session)
                .collect::<Vec<_>>()
        };
        let mut workspace_ids = Vec::with_capacity(removed.len());
        for session in removed {
            workspace_ids.push(session.workspace_id.clone());
            self.set_status(
                &session.server_id,
                Some(&session.workspace_id),
                RemoteConnectionState::Disconnected,
                None,
            )?;
            session.stop().await;
        }
        Ok(workspace_ids)
    }

    pub(crate) fn server_ids_with_sessions(&self) -> Result<HashSet<String>, ApiError> {
        let sessions = self
            .sessions
            .lock()
            .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
        Ok(sessions
            .values()
            .map(|session| session.server_id.clone())
            .collect())
    }

    pub(crate) fn session_summaries_for_server(
        &self,
        server_id: &str,
    ) -> Result<Vec<RemoteWorkspaceSessionSummary>, ApiError> {
        let sessions = self
            .sessions
            .lock()
            .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
        Ok(sessions
            .values()
            .filter(|session| session.server_id == server_id)
            .map(|session| session.summary())
            .collect())
    }

    pub(crate) fn workspace_state(
        &self,
        server_id: &str,
        workspace_id: &str,
    ) -> Result<Option<RemoteConnectionState>, ApiError> {
        if let Some(session) = self.session(&session_key(server_id, workspace_id))? {
            return Ok(Some(session.status_snapshot().state));
        }
        Ok(self
            .get_status(server_id, Some(workspace_id))?
            .map(|status| status.state))
    }

    pub(crate) fn server_state(
        &self,
        server_id: &str,
    ) -> Result<Option<RemoteConnectionState>, ApiError> {
        let sessions = self.session_summaries_for_server(server_id)?;
        if sessions.iter().any(|session| session.status == "ready") {
            return Ok(Some(RemoteConnectionState::Ready));
        }
        if sessions
            .iter()
            .any(|session| session.status == "reconnecting" || session.status == "degraded")
        {
            return Ok(Some(RemoteConnectionState::Degraded));
        }
        Ok(self.get_status(server_id, None)?.map(|status| status.state))
    }

    #[cfg(test)]
    pub(crate) fn insert_fake_session_for_test(
        &self,
        server_id: &str,
        workspace_id: &str,
        remote_path: &str,
        local_port: u16,
        token: &str,
    ) {
        let session = Arc::new(RemoteWorkspaceSession {
            server_id: server_id.to_string(),
            workspace_id: workspace_id.to_string(),
            remote_path: remote_path.to_string(),
            sidecar_identity: RemoteSidecarIdentity {
                version: "test".to_string(),
                target: "linux-x64".to_string(),
                build_id: "foco-sidecar-v2:sha256:test".to_string(),
            },
            target: "linux-x64".to_string(),
            local_port,
            remote_port: local_port,
            token: token.to_string(),
            started_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            ssh: AsyncMutex::new(None),
            sidecar: AsyncMutex::new(None),
            forward_stop: AsyncMutex::new(None),
            forward_task: AsyncMutex::new(None),
            control_task: AsyncMutex::new(None),
            health_task: AsyncMutex::new(None),
            status: Arc::new(Mutex::new(RemoteSessionStatus::new(
                RemoteConnectionState::Ready,
                None,
            ))),
            active_runs: Arc::new(Mutex::new(Vec::new())),
        });
        let mut sessions = self.sessions.lock().expect("remote sessions");
        sessions.insert(session_key(server_id, workspace_id), session);
    }

    #[cfg(test)]
    pub(crate) fn remove_fake_session_for_test(&self, workspace_id: &str) {
        let mut sessions = self.sessions.lock().expect("remote sessions");
        sessions.retain(|_, session| session.workspace_id != workspace_id);
    }

    fn session(&self, key: &str) -> Result<Option<Arc<RemoteWorkspaceSession>>, ApiError> {
        let sessions = self
            .sessions
            .lock()
            .map_err(|_| ApiError::internal("remote workspace session lock is poisoned"))?;
        Ok(sessions.get(key).cloned())
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct RemoteWorkspaceSessionResponse {
    session: Option<RemoteWorkspaceSessionSummary>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct RemoteWorkspaceSessionsResponse {
    sessions: Vec<RemoteWorkspaceSessionSummary>,
}

pub(crate) async fn connect_remote_workspace(
    State(state): State<AppState>,
    AxumPath((server_id, workspace_id)): AxumPath<(String, String)>,
) -> Result<Json<RemoteWorkspaceSessionResponse>, ApiError> {
    let session = state
        .remote_workspace_manager
        .connect_workspace(state.clone(), &server_id, &workspace_id)
        .await?;
    Ok(Json(RemoteWorkspaceSessionResponse {
        session: Some(session),
    }))
}

pub(crate) async fn disconnect_remote_workspace(
    State(state): State<AppState>,
    AxumPath((server_id, workspace_id)): AxumPath<(String, String)>,
) -> Result<Json<RemoteWorkspaceSessionResponse>, ApiError> {
    let removed = state
        .remote_workspace_manager
        .disconnect_workspace(&server_id, &workspace_id)
        .await?;
    state
        .openai_resp_ws_sessions
        .invalidate_workspace(&workspace_id)
        .await;
    Ok(Json(RemoteWorkspaceSessionResponse {
        session: removed.then(|| RemoteWorkspaceSessionSummary {
            server_id,
            workspace_id,
            remote_path: String::new(),
            target: String::new(),
            local_port: 0,
            remote_port: 0,
            started_at: String::new(),
            status: RemoteConnectionState::Disconnected.as_str().to_string(),
            last_error: None,
            status_updated_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            active_runs: Vec::new(),
        }),
    }))
}

pub(crate) async fn remote_workspace_sessions(
    State(state): State<AppState>,
    AxumPath(server_id): AxumPath<String>,
) -> Result<Json<RemoteWorkspaceSessionsResponse>, ApiError> {
    Ok(Json(RemoteWorkspaceSessionsResponse {
        sessions: state
            .remote_workspace_manager
            .session_summaries_for_server(&server_id)?,
    }))
}

#[derive(Debug)]
struct PartialRemoteConnect {
    ssh: Option<Arc<SshSession>>,
    sidecar: Option<SshSpawnedExec>,
    forward_stop: Option<oneshot::Sender<()>>,
    forward_task: Option<JoinHandle<()>>,
    control_task: Option<JoinHandle<()>>,
}

impl PartialRemoteConnect {
    fn with_ssh(ssh: Arc<SshSession>) -> Self {
        Self {
            ssh: Some(ssh),
            sidecar: None,
            forward_stop: None,
            forward_task: None,
            control_task: None,
        }
    }

    fn ssh_ref(&self) -> &Arc<SshSession> {
        self.ssh
            .as_ref()
            .expect("ssh session present on partial connect")
    }

    async fn abort(mut self) {
        if let Some(task) = self.control_task.take() {
            task.abort();
        }
        if let Some(stop) = self.forward_stop.take() {
            let _ = stop.send(());
        }
        if let Some(task) = self.forward_task.take() {
            task.abort();
            let _ = task.await;
        }
        if let Some(mut sidecar) = self.sidecar.take() {
            sidecar.close().await;
        }
        if let Some(session) = self.ssh.take() {
            let _ = session.disconnect().await;
        }
    }

    fn take_into_session(
        mut self,
    ) -> (
        Arc<SshSession>,
        SshSpawnedExec,
        oneshot::Sender<()>,
        JoinHandle<()>,
        JoinHandle<()>,
    ) {
        (
            self.ssh
                .take()
                .expect("ssh session for ready remote workspace"),
            self.sidecar
                .take()
                .expect("sidecar for ready remote workspace"),
            self.forward_stop
                .take()
                .expect("forward stop for ready remote workspace"),
            self.forward_task
                .take()
                .expect("forward task for ready remote workspace"),
            self.control_task
                .take()
                .expect("control task for ready remote workspace"),
        )
    }
}

#[derive(Debug)]
struct RemoteWorkspaceSession {
    // ponytail: one russh transport + sidecar exec + direct-tcpip bridges per remote workspace.
    server_id: String,
    workspace_id: String,
    remote_path: String,
    sidecar_identity: RemoteSidecarIdentity,
    target: String,
    local_port: u16,
    remote_port: u16,
    token: String,
    started_at: String,
    ssh: AsyncMutex<Option<Arc<SshSession>>>,
    sidecar: AsyncMutex<Option<SshSpawnedExec>>,
    forward_stop: AsyncMutex<Option<oneshot::Sender<()>>>,
    forward_task: AsyncMutex<Option<JoinHandle<()>>>,
    control_task: AsyncMutex<Option<JoinHandle<()>>>,
    health_task: AsyncMutex<Option<JoinHandle<()>>>,
    status: Arc<Mutex<RemoteSessionStatus>>,
    active_runs: Arc<Mutex<Vec<RemoteActiveRunSummary>>>,
}

impl RemoteWorkspaceSession {
    fn matches_expected_identity(
        &self,
        server_id: &str,
        workspace_id: &str,
        expected_identity: &RemoteSidecarIdentity,
    ) -> bool {
        remote_workspace_session_identity_matches(
            &self.server_id,
            &self.workspace_id,
            &self.sidecar_identity,
            server_id,
            workspace_id,
            expected_identity,
        )
    }

    fn summary(&self) -> RemoteWorkspaceSessionSummary {
        let active_runs = self
            .active_runs
            .lock()
            .map(|runs| runs.clone())
            .unwrap_or_default();
        let status = self.status_snapshot();
        RemoteWorkspaceSessionSummary {
            server_id: self.server_id.clone(),
            workspace_id: self.workspace_id.clone(),
            remote_path: self.remote_path.clone(),
            target: self.target.clone(),
            local_port: self.local_port,
            remote_port: self.remote_port,
            started_at: self.started_at.clone(),
            status: status.state.as_str().to_string(),
            last_error: status.last_error,
            status_updated_at: status.updated_at,
            active_runs,
        }
    }

    fn status_snapshot(&self) -> RemoteSessionStatus {
        self.status
            .lock()
            .map(|status| status.clone())
            .unwrap_or_else(|_| {
                RemoteSessionStatus::new(
                    RemoteConnectionState::Degraded,
                    Some("remote workspace status lock is poisoned".to_string()),
                )
            })
    }

    async fn stop(&self) {
        set_session_status(&self.status, RemoteConnectionState::Disconnected, None);
        if let Some(task) = self.control_task.lock().await.take() {
            task.abort();
        }
        if let Some(task) = self.health_task.lock().await.take() {
            task.abort();
        }
        let _ = shutdown_remote_sidecar(self.local_port, &self.token).await;
        if let Some(stop) = self.forward_stop.lock().await.take() {
            let _ = stop.send(());
        }
        if let Some(task) = self.forward_task.lock().await.take() {
            // Allow the forward loop to abort bridge tasks on stop_rx before hard abort.
            let abort = task.abort_handle();
            match timeout(Duration::from_secs(2), task).await {
                Ok(_) => {}
                Err(_) => {
                    abort.abort();
                }
            }
        }
        if let Some(mut sidecar) = self.sidecar.lock().await.take() {
            sidecar.close().await;
        }
        if let Some(session) = self.ssh.lock().await.take() {
            let _ = session.disconnect().await;
        }
    }
}

