async fn remote_sidecar_context_usage(
    State(state): State<RemoteSidecarState>,
    Json(request): Json<ContextUsageRequest>,
) -> Result<Json<ContextUsageResponse>, axum::response::Response> {
    let ContextUsageRequest {
        chat_id,
        model_id,
        provider_id,
        thinking_level,
        skill_ids,
        assistant_draft,
        assistant_draft_reasoning,
    } = request;
    let chat_id = chat_id
        .map(|chat_id| chat_id.trim().to_string())
        .filter(|chat_id| !chat_id.is_empty())
        .ok_or_else(|| ApiError::bad_request("chat id must not be empty").into_response())?;

    remote_sidecar_validate_context_preview_model(&state, &model_id, provider_id.as_deref())
        .map_err(|error| error.into_response())?;

    let bundle = state
        .runtime_config
        .lock()
        .map_err(|_| {
            ApiError::internal("remote sidecar runtime configuration lock is poisoned")
                .into_response()
        })?
        .clone();
    let tool_catalog = remote_sidecar_tool_catalog(&state, bundle.as_ref(), None).await?;
    let database = sidecar_workspace_database(&state)?;
    database
        .chat(&chat_id)
        .map_err(|error| ApiError::from_workspace_error(error).into_response())?
        .ok_or_else(|| {
            ApiError::bad_request(format!("chat was not found: {chat_id}")).into_response()
        })?;

    let requested_skill_ids = skill_ids.unwrap_or_default();
    let prepared = remote_sidecar_prepare_chat_context_with_options(
        &state,
        &database,
        &chat_id,
        RemoteChatContextOptions {
            assistant_message_id: None,
            model_id: &model_id,
            requested_skill_ids: &requested_skill_ids,
            requested_thinking_level: thinking_level,
            assistant_draft: assistant_draft.as_deref(),
            assistant_draft_reasoning: assistant_draft_reasoning.as_deref(),
            tool_catalog,
            session_mode: None,
        },
    )?;
    if prepared.context_budget.context_window == u64::MAX {
        return Err(ApiError::internal(
            "remote runtime configuration changed while context usage was prepared",
        )
        .into_response());
    }

    let usage = context_usage_response(ContextUsageInput {
        messages: &prepared.provider_request.messages,
        message_source_sequences: &prepared.message_source_sequences,
        message_context_sources: &prepared.message_context_sources,
        active_tool_start_index: prepared.active_tool_start_index,
        context_budget: &prepared.context_budget,
        memory_context_tokens: 0,
        memory_budget_tokens: 0,
    })
    .map_err(|error| error.into_response())?;

    Ok(Json(usage))
}

fn remote_sidecar_validate_context_preview_model(
    state: &RemoteSidecarState,
    model_id: &str,
    _legacy_provider_id: Option<&str>,
) -> Result<(), ApiError> {
    if model_id.trim().is_empty() {
        return Err(ApiError::bad_request("model id must not be empty"));
    }

    let runtime_config = state
        .runtime_config
        .lock()
        .map_err(|_| ApiError::internal("remote runtime configuration lock is unavailable"))?;
    let bundle = runtime_config.as_ref().ok_or_else(|| {
        ApiError::bad_request("remote runtime configuration has not been synchronized")
    })?;
    let model = bundle
        .payload
        .models
        .iter()
        .find(|model| model.id == model_id)
        .ok_or_else(|| {
            ApiError::bad_request(format!(
                "remote context preview model was not found: {model_id}"
            ))
        })?;
    if !model.enabled {
        return Err(ApiError::bad_request(format!(
            "remote context preview model is disabled: {model_id}"
        )));
    }
    if model.limits.is_none() {
        return Err(ApiError::bad_request(format!(
            "remote context preview model has no context limits: {model_id}"
        )));
    }

    Ok(())
}

// Dead helpers removed: sidecar detail is always unavailable; main-process Detail API is the source of truth.

async fn remote_sidecar_ai_statistics_detail(
    State(state): State<RemoteSidecarState>,
    AxumPath(request_id): AxumPath<String>,
) -> Result<Json<Value>, axum::response::Response> {
    let request_id = request_id.trim();
    if request_id.is_empty() {
        return Err(ApiError::bad_request("request id must not be empty").into_response());
    }
    let database = sidecar_workspace_database(&state)?;
    let request = database
        .llm_request(request_id)
        .map_err(|e| ApiError::from_workspace_error(e).into_response())?
        .ok_or_else(|| {
            ApiError::bad_request(format!("LLM request was not found: {request_id}"))
                .into_response()
        })?;
    let events = database
        .llm_request_events(request_id)
        .map_err(|e| ApiError::from_workspace_error(e).into_response())?;
    Ok(Json(json!({
        "request": {
            "id": request.id,
            "workspaceId": state.workspace_id,
            "workspaceName": state.workspace_id,
            "chatId": request.chat_id,
            "chatTitle": null,
            "requestKind": request.request_kind,
            "providerId": request.provider_id,
            "modelId": request.model_id,
            "requestStartedAt": request.request_started_at,
            "firstTokenAt": request.first_token_at,
            "completedAt": request.completed_at,
            "inputTokens": request.input_tokens,
            "outputTokens": request.output_tokens,
            "cacheReadTokens": request.cache_read_tokens,
            "cacheWriteTokens": request.cache_write_tokens,
            "reasoningTokens": request.reasoning_tokens,
            "cacheRatio": request.cache_ratio,
            "firstTokenLatencyMs": request.first_token_latency_ms,
            "totalLatencyMs": request.total_latency_ms,
            "statusCode": request.status_code,
            "finalState": request.final_state,
            // Sidecar mirror is not a provider detail source. Wire lives on the main process.
            "requestDetailStatus": if request.final_state == "running" {
                "pending"
            } else {
                "unavailable"
            },
            "responseDetailStatus": if request.final_state == "running" {
                "pending"
            } else {
                "unavailable"
            },
            "requestBody": null,
            "responseBody": null,
        },
        "events": events.into_iter().map(|event| json!({
            "id": event.id,
            "sequence": event.sequence,
            "eventAt": event.event_at,
            "eventType": event.event_type,
            "rawChunk": event.raw_chunk_json.as_deref().and_then(|value| serde_json::from_str::<Value>(value).ok()),
            "normalizedEvent": serde_json::from_str::<Value>(&event.normalized_event_json).unwrap_or(Value::Null),
        })).collect::<Vec<_>>(),
    })))
}

async fn remote_sidecar_passthrough_unavailable() -> Result<Json<Value>, axum::response::Response> {
    Err(
        ApiError::bad_gateway("remote sidecar runtime endpoint is not available in this build")
            .into_response(),
    )
}

async fn remote_sidecar_file_tree(
    State(state): State<RemoteSidecarState>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let root =
        crate::http::workspaces::workspace_file_tree_response(sidecar_workspace_path(&state))
            .map_err(|e| e.into_response())?;
    Ok(Json(serde_json::json!({ "root": root })))
}

async fn remote_sidecar_file_children(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let path = query.get("path").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let list_path = crate::http::workspaces::workspace_file_list_path(ws_path, path)
        .map_err(|e| e.into_response())?;
    let children =
        crate::http::workspaces::workspace_file_tree_children(ws_path, &list_path, 0, false)
            .map_err(|e| e.into_response())?;
    Ok(Json(
        serde_json::json!({ "path": path, "children": children }),
    ))
}

async fn remote_sidecar_file_content(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let rel_path = payload.get("path").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let abs_path = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    let content = std::fs::read_to_string(&abs_path).map_err(|source| {
        ApiError::bad_request(format!("failed to read remote file {rel_path}: {source}"))
            .into_response()
    })?;
    Ok(Json(
        serde_json::json!({ "content": content, "path": rel_path }),
    ))
}

async fn remote_sidecar_file_save(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let rel_path = payload.get("path").map(String::as_str).unwrap_or("");
    let content = payload.get("content").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let abs_path = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    std::fs::write(&abs_path, content.as_bytes()).map_err(|source| {
        ApiError::internal(format!("failed to save remote file {rel_path}: {source}"))
            .into_response()
    })?;
    Ok(Json(
        serde_json::json!({ "content": content, "path": rel_path }),
    ))
}

async fn remote_sidecar_file_delete(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let rel_path = payload.get("path").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let abs_path = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    let meta = std::fs::metadata(&abs_path).map_err(|source| {
        ApiError::bad_request(format!("remote file not found {rel_path}: {source}")).into_response()
    })?;
    if meta.is_dir() {
        std::fs::remove_dir_all(&abs_path).map_err(|source| {
            ApiError::internal(format!("failed to delete remote dir {rel_path}: {source}"))
                .into_response()
        })?;
    } else {
        std::fs::remove_file(&abs_path).map_err(|source| {
            ApiError::internal(format!("failed to delete remote file {rel_path}: {source}"))
                .into_response()
        })?;
    }
    let parent = rel_path
        .rsplit_once('/')
        .map(|(p, _)| p.to_string())
        .unwrap_or_default();
    let list_path = crate::http::workspaces::workspace_file_list_path(ws_path, &parent)
        .map_err(|e| e.into_response())?;
    let children =
        crate::http::workspaces::workspace_file_tree_children(ws_path, &list_path, 0, false)
            .map_err(|e| e.into_response())?;
    Ok(Json(
        serde_json::json!({ "path": parent, "children": children }),
    ))
}

async fn remote_sidecar_file_rename(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<HashMap<String, String>>,
) -> Result<Json<serde_json::Value>, axum::response::Response> {
    let rel_path = payload.get("path").map(String::as_str).unwrap_or("");
    let new_name = payload.get("newName").map(String::as_str).unwrap_or("");
    if new_name.is_empty() {
        return Err(ApiError::bad_request("newName must not be empty").into_response());
    }
    let ws_path = sidecar_workspace_path(&state);
    let src = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    let dst = src
        .parent()
        .ok_or_else(|| ApiError::bad_request("workspace root cannot be renamed").into_response())?
        .join(new_name);
    if dst.exists() {
        return Err(
            ApiError::bad_request(format!("target already exists: {}", dst.display()))
                .into_response(),
        );
    }
    std::fs::rename(&src, &dst).map_err(|source| {
        ApiError::internal(format!("failed to rename remote file {rel_path}: {source}"))
            .into_response()
    })?;
    let parent = rel_path
        .rsplit_once('/')
        .map(|(p, _)| p.to_string())
        .unwrap_or_default();
    let list_path = crate::http::workspaces::workspace_file_list_path(ws_path, &parent)
        .map_err(|e| e.into_response())?;
    let children =
        crate::http::workspaces::workspace_file_tree_children(ws_path, &list_path, 0, false)
            .map_err(|e| e.into_response())?;
    Ok(Json(
        serde_json::json!({ "path": parent, "children": children }),
    ))
}

async fn remote_sidecar_memory_list(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<Json<Value>, axum::response::Response> {
    let scope = MemoryScope::parse(
        query
            .get("scope")
            .map(String::as_str)
            .unwrap_or("workspace"),
    )
    .map_err(|e| ApiError::bad_request(e.to_string()).into_response())?;
    if scope == MemoryScope::Global {
        return Err(
            ApiError::bad_request("global memory stays in the local broker").into_response(),
        );
    }
    let chat_id = query
        .get("chatId")
        .or_else(|| query.get("chat_id"))
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    if scope == MemoryScope::Chat && chat_id.is_none() {
        return Err(ApiError::bad_request("chat memory listing requires chatId").into_response());
    }
    let status = MemoryStatus::parse(query.get("status").map(String::as_str).unwrap_or("active"))
        .map_err(|e| ApiError::bad_request(e.to_string()).into_response())?;
    let page = query
        .get("page")
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(1)
        .max(1);
    let page_size = query
        .get("pageSize")
        .or_else(|| query.get("page_size"))
        .or_else(|| query.get("limit"))
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(20)
        .clamp(1, 200);
    let offset = page.saturating_sub(1).saturating_mul(page_size);
    let query_text = query.get("query").map(String::as_str);
    let database = foco_store::open_workspace_memory_database(sidecar_workspace_path(&state))
        .map_err(|error| ApiError::from_memory_error(error).into_response())?;
    let total_count = database
        .count_facts_for_scope(chat_id.as_deref(), status, None, query_text)
        .map_err(|e| ApiError::from_memory_error(e).into_response())?;
    let memories = database
        .list_facts_for_scope_page(
            chat_id.as_deref(),
            status,
            None,
            query_text,
            page_size,
            offset,
        )
        .map_err(|e| ApiError::from_memory_error(e).into_response())?;
    Ok(Json(json!({
        "memories": memories,
        "extractionJobs": [],
        "remote": { "status": "available" },
        "page": page,
        "pageSize": page_size,
        "totalCount": total_count,
        "totalPages": if total_count == 0 { 0 } else { total_count.div_ceil(page_size) },
    })))
}

async fn remote_sidecar_memory_manual(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<Value>,
) -> Result<Json<Value>, axum::response::Response> {
    let scope = MemoryScope::parse(
        payload
            .get("scope")
            .and_then(Value::as_str)
            .unwrap_or("workspace"),
    )
    .map_err(|e| ApiError::bad_request(e.to_string()).into_response())?;
    if scope == MemoryScope::Global {
        return Err(
            ApiError::bad_request("global memory stays in the local broker").into_response(),
        );
    }
    let kind = MemoryKind::parse(
        payload
            .get("kind")
            .and_then(Value::as_str)
            .unwrap_or("project_fact"),
    )
    .map_err(|e| ApiError::bad_request(e.to_string()).into_response())?;
    let fact = payload
        .get("fact")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::bad_request("memory fact must not be empty").into_response())?;
    let chat_id = payload
        .get("chatId")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if scope == MemoryScope::Chat && chat_id.is_none() {
        return Err(ApiError::bad_request("chat memory requires chatId").into_response());
    }
    let mut database = foco_store::open_workspace_memory_database(sidecar_workspace_path(&state))
        .map_err(|error| ApiError::from_memory_error(error).into_response())?;
    let source_id = unique_id("remote-memory-source");
    let memory_id = unique_id("remote-memory-fact");
    database
        .insert_source(NewMemorySource {
            id: &source_id,
            scope,
            chat_id,
            source_type: MemorySourceType::ManualNote,
            source_id: None,
            title: "Remote manual memory",
            content: fact,
            metadata_json: "{}",
        })
        .map_err(|e| ApiError::from_memory_error(e).into_response())?;
    database
        .insert_fact(NewMemoryFact {
            id: &memory_id,
            scope,
            chat_id,
            status: MemoryStatus::Active,
            kind,
            fact,
            confidence: payload.get("confidence").and_then(Value::as_f64),
            pinned: payload
                .get("pinned")
                .and_then(Value::as_bool)
                .unwrap_or(false),
            source_ids: &[source_id.as_str()],
            metadata_json: "{}",
        })
        .map_err(|e| ApiError::from_memory_error(e).into_response())?;
    let memory = database
        .fact(&memory_id)
        .map_err(|e| ApiError::from_memory_error(e).into_response())?;
    Ok(Json(json!({ "memory": memory })))
}

async fn remote_sidecar_memory_get(
    State(state): State<RemoteSidecarState>,
    AxumPath(path): AxumPath<String>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<Json<Value>, axum::response::Response> {
    if path == "sources" {
        let scope = MemoryScope::parse(query.get("scope").map(String::as_str).unwrap_or(""))
            .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
        if scope == MemoryScope::Global {
            return Err(
                ApiError::bad_request("global memory stays in the local broker").into_response(),
            );
        }
        let memory_id = query
            .get("memoryId")
            .map(String::as_str)
            .map(str::trim)
            .filter(|memory_id| !memory_id.is_empty())
            .ok_or_else(|| ApiError::bad_request("memoryId must not be empty").into_response())?;
        let database = foco_store::open_workspace_memory_database(sidecar_workspace_path(&state))
            .map_err(|error| ApiError::from_memory_error(error).into_response())?;
        let sources = database
            .sources_for_fact(memory_id)
            .map_err(|error| ApiError::from_memory_error(error).into_response())?;
        return Ok(Json(json!({ "sources": sources })));
    }

    Err(remote_sidecar_memory_unimplemented_response(&path))
}

async fn remote_sidecar_memory_mutation(
    AxumPath(path): AxumPath<String>,
) -> Result<Json<Value>, axum::response::Response> {
    Err(remote_sidecar_memory_unimplemented_response(&path))
}

fn remote_sidecar_memory_unimplemented_response(path: &str) -> axum::response::Response {
    ApiError::from_status_message(
        StatusCode::NOT_IMPLEMENTED,
        format!(
            "remote workspace Memory endpoint is not implemented on the sidecar: {path}; the request was not sent to the main-process workspace database"
        ),
    )
    .into_response()
}

async fn remote_sidecar_skill_install(
    State(state): State<RemoteSidecarState>,
    Json(request): Json<crate::http::skill_store::SkillStoreInstallRequest>,
) -> Result<Json<crate::http::skill_store::SkillStoreInstallResponse>, axum::response::Response> {
    let install_path = crate::http::skill_store::install_skill_files_to_target_dir(
        &sidecar_workspace_path(&state)
            .join(".agents")
            .join("skills"),
        &request.skill_id,
        &request.files,
        request.overwrite,
    )
    .map_err(|e| e.into_response())?;
    let discovery = crate::skills::discover_workspace_skills_for_path(
        &state.workspace_id,
        &state.workspace_id,
        sidecar_workspace_path(&state),
    );
    Ok(Json(crate::http::skill_store::SkillStoreInstallResponse {
        target: foco_store::config::SKILL_SCOPE_WORKSPACE.to_string(),
        workspace_id: Some(state.workspace_id),
        path: install_path.display().to_string(),
        detected: discovery.skills,
    }))
}

async fn remote_sidecar_skills_discover(
    State(state): State<RemoteSidecarState>,
) -> Result<Json<Value>, axum::response::Response> {
    let workspace_discovery = crate::skills::discover_workspace_skills_for_path(
        &state.workspace_id,
        &state.workspace_id,
        sidecar_workspace_path(&state),
    );
    let remote_global_discovery = remote_sidecar_discover_remote_global_skills(&state);
    let mut skills = remote_global_discovery.skills;
    skills.extend(workspace_discovery.skills);
    skills.sort_by(|left, right| {
        left.scope
            .cmp(&right.scope)
            .then_with(|| left.workspace_name.cmp(&right.workspace_name))
            .then_with(|| left.id.cmp(&right.id))
            .then_with(|| left.path.cmp(&right.path))
    });
    let mut errors = remote_global_discovery.errors;
    errors.extend(workspace_discovery.errors);
    let mut required_disabled = remote_global_discovery.required_disabled;
    required_disabled.extend(workspace_discovery.required_disabled);
    required_disabled.sort();
    required_disabled.dedup();
    Ok(Json(json!({
        "detected": skills,
        "errors": errors,
        "requiredDisabled": required_disabled,
    })))
}

async fn remote_sidecar_hooks_settings(
    State(state): State<RemoteSidecarState>,
) -> Result<Json<Value>, axum::response::Response> {
    let workspace_path = sidecar_workspace_path(&state);
    let workspace_config = foco_store::config::load_workspace_hook_config(workspace_path)
        .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
    let (_, _, global_hooks, _, _) = remote_sidecar_hook_environment(&state, None)
        .await
        .map_err(|error| ApiError::bad_gateway(error).into_response())?;
    let effective = crate::hooks::effective_hook_summaries(&global_hooks, workspace_path)
        .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
    let recent_runs = WorkspaceDatabase::open_or_create(workspace_path)
        .map_err(|error| ApiError::from_workspace_error(error).into_response())?
        .hook_runs(50)
        .map_err(|error| ApiError::from_workspace_error(error).into_response())?
        .into_iter()
        .filter(|record| record.workspace_id == state.workspace_id)
        .map(crate::hook_run_summary_row)
        .collect::<Vec<_>>();

    Ok(Json(json!({
        "supportedEvents": foco_store::config::SUPPORTED_HOOK_EVENTS,
        "unsupportedEvents": foco_store::config::UNSUPPORTED_HOOK_EVENTS,
        "global": {
            "source": "global",
            "path": "brokered://global-hook-config",
            "workspaceId": Value::Null,
            "config": global_hooks,
        },
        "workspace": {
            "source": "workspace",
            "path": foco_store::config::workspace_hook_config_path(workspace_path).display().to_string(),
            "workspaceId": state.workspace_id,
            "config": workspace_config,
        },
        "effective": effective,
        "recentRuns": recent_runs,
    })))
}

async fn remote_sidecar_hooks_save(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<Value>,
) -> Result<Json<Value>, axum::response::Response> {
    let config_value = payload.get("config").cloned().unwrap_or(payload);
    let workspace_config: foco_store::config::HookConfig = serde_json::from_value(config_value)
        .map_err(|error| {
            ApiError::bad_request(format!("invalid hook config: {error}")).into_response()
        })?;
    let (_, _, _, mut validation_config, _) =
        remote_sidecar_hook_environment(&state, None)
            .await
            .map_err(|error| ApiError::bad_gateway(error).into_response())?;
    validation_config.hooks = workspace_config.clone();
    validation_config
        .validate(Some(&foco_store::config::workspace_hook_config_path(
            sidecar_workspace_path(&state),
        )))
        .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
    foco_store::config::save_workspace_hook_config(
        sidecar_workspace_path(&state),
        &workspace_config,
    )
    .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
    remote_sidecar_hooks_settings(State(state)).await
}

async fn remote_sidecar_import_claude_hooks(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<Value>,
) -> Result<Json<Value>, axum::response::Response> {
    if payload
        .get("target")
        .and_then(Value::as_str)
        .is_some_and(|target| target.trim() != "workspace")
    {
        return Err(ApiError::bad_request(
            "remote Claude Hook import only supports target=workspace",
        )
        .into_response());
    }
    if let Some(workspace_id) = payload.get("workspaceId").and_then(Value::as_str)
        && workspace_id.trim() != state.workspace_id
    {
        return Err(ApiError::bad_request(
            "workspaceId does not match the connected remote workspace",
        )
        .into_response());
    }

    let workspace_path = sidecar_workspace_path(&state);
    let source_paths = crate::claude_hook_settings_paths(workspace_path);
    let save_path = foco_store::config::workspace_hook_config_path(workspace_path);
    let (imported, imported_files, mut validation_errors) =
        crate::import_claude_hook_config(&source_paths).map_err(|error| error.into_response())?;
    if imported_files.is_empty() {
        validation_errors.push(format!(
            "no Claude hook settings were found under {}",
            workspace_path.join(".claude").display()
        ));
    }
    if validation_errors.is_empty() {
        let (_, _, _, mut validation_config, _) = remote_sidecar_hook_environment(&state, None)
            .await
            .map_err(|error| ApiError::bad_gateway(error).into_response())?;
        validation_config.hooks = imported.clone();
        if let Err(error) = validation_config.validate(Some(&save_path)) {
            validation_errors.push(error.to_string());
        }
    }
    if validation_errors.is_empty() {
        foco_store::config::save_workspace_hook_config(workspace_path, &imported)
            .map_err(|error| ApiError::bad_request(error.to_string()).into_response())?;
    }

    Ok(Json(json!({
        "saved": validation_errors.is_empty(),
        "target": "workspace",
        "path": save_path.display().to_string(),
        "importedFiles": imported_files,
        "validationErrors": validation_errors,
        "config": imported,
    })))
}

async fn remote_sidecar_test_hooks(
    State(state): State<RemoteSidecarState>,
    Json(payload): Json<Value>,
) -> Result<Json<crate::hooks::HookRunSummary>, axum::response::Response> {
    let event = payload
        .get("event")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|event| !event.is_empty())
        .ok_or_else(|| ApiError::bad_request("hook event must not be empty").into_response())?;
    if foco_store::config::UNSUPPORTED_HOOK_EVENTS.contains(&event) {
        return Err(ApiError::bad_request(format!(
            "{event} is a Claude Code hook event that Foco does not support yet"
        ))
        .into_response());
    }
    if !foco_store::config::SUPPORTED_HOOK_EVENTS.contains(&event) {
        return Err(ApiError::bad_request(format!(
            "{event} is unsupported; expected one of {}",
            foco_store::config::SUPPORTED_HOOK_EVENTS.join(", ")
        ))
        .into_response());
    }
    let (_, hook_runtime, global_hooks, global_config, retry_count) =
        remote_sidecar_hook_environment(&state, None)
            .await
            .map_err(|error| ApiError::bad_gateway(error).into_response())?;
    let summary = hook_runtime
        .run_hooks(HookRunRequest {
            global_config: &global_hooks,
            api_audit_save_details: api_audit_save_details(&global_config),
            workspace_id: &state.workspace_id,
            workspace_path: sidecar_workspace_path(&state),
            event,
            match_value: payload
                .get("matchValue")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned),
            chat_id: None,
            run_id: None,
            session_id: None,
            tool_call_id: None,
            model_id: payload.get("modelId").and_then(Value::as_str),
            provider_id: payload.get("providerId").and_then(Value::as_str),
            provider_config: None,
            llm_request_retry_count: retry_count,
            permission_mode: None,
            payload: payload.get("payload").cloned().unwrap_or_else(|| json!({})),
        })
        .await;
    Ok(Json(summary))
}

async fn remote_sidecar_hook_runs(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<Json<Value>, axum::response::Response> {
    let limit = query
        .get("limit")
        .and_then(|value| value.parse::<i64>().ok())
        .unwrap_or(50)
        .clamp(1, 200);
    let runs =
        foco_store::workspace::WorkspaceDatabase::open_or_create(sidecar_workspace_path(&state))
            .map_err(|e| ApiError::from_workspace_error(e).into_response())?
            .hook_runs(limit)
            .map_err(|e| ApiError::from_workspace_error(e).into_response())?
            .into_iter()
            .filter(|record| record.workspace_id == state.workspace_id)
            .map(crate::hook_run_summary_row)
            .collect::<Vec<_>>();
    Ok(Json(json!({ "runs": runs })))
}

async fn remote_sidecar_hook_run_detail(
    State(state): State<RemoteSidecarState>,
    AxumPath(hook_run_id): AxumPath<String>,
) -> Result<Json<Value>, axum::response::Response> {
    let hook_run_id = hook_run_id.trim();
    if hook_run_id.is_empty() {
        return Err(ApiError::bad_request("hook run id must not be empty").into_response());
    }
    let run =
        foco_store::workspace::WorkspaceDatabase::open_or_create(sidecar_workspace_path(&state))
            .map_err(|e| ApiError::from_workspace_error(e).into_response())?
            .hook_run(hook_run_id)
            .map_err(|e| ApiError::from_workspace_error(e).into_response())?
            .ok_or_else(|| {
                ApiError::bad_request(format!("hook run was not found: {hook_run_id}"))
                    .into_response()
            })?;
    if run.workspace_id != state.workspace_id {
        return Err(ApiError::bad_request(format!(
            "hook run '{}' does not belong to workspace '{}'",
            run.id, state.workspace_id
        ))
        .into_response());
    }
    let run = crate::hook_run_detail_from_record(run).map_err(|error| error.into_response())?;
    Ok(Json(json!({ "run": run })))
}

async fn remote_sidecar_file_blob(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<axum::response::Response, axum::response::Response> {
    let rel_path = query.get("path").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let abs_path = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    let bytes = std::fs::read(&abs_path).map_err(|source| {
        ApiError::bad_request(format!("failed to read remote file {rel_path}: {source}"))
            .into_response()
    })?;
    let content_type = crate::http::workspaces::workspace_image_content_type(&bytes)
        .map_err(|e| e.into_response())?;
    Ok(axum::response::Response::builder()
        .status(axum::http::StatusCode::OK)
        .header(axum::http::header::CONTENT_TYPE, content_type)
        .header(axum::http::header::CACHE_CONTROL, "private, max-age=60")
        .body(axum::body::Body::from(bytes))
        .expect("sidecar blob response is valid"))
}

async fn remote_sidecar_file_download(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<HashMap<String, String>>,
) -> Result<axum::response::Response, axum::response::Response> {
    let rel_path = query.get("path").map(String::as_str).unwrap_or("");
    let ws_path = sidecar_workspace_path(&state);
    let abs_path = crate::http::workspaces::workspace_file_path(ws_path, rel_path)
        .map_err(|e| e.into_response())?;
    crate::http::workspaces::workspace_file_download_response(&abs_path, rel_path)
        .map_err(|e| e.into_response())
}

/// Serve a single preview resource for the main-process preview host proxy.
///
/// Query:
/// - `path`: workspace-relative resource path (already resolved by main; re-validated here)
/// - `root`: workspace-relative preview root (parent of entry HTML; empty = workspace root)
///
/// Does not accept PreviewSession tokens, Foco cookies, provider secrets, or arbitrary
/// browser headers beyond what the bearer-auth middleware already requires.
async fn remote_sidecar_preview_file(
    State(state): State<RemoteSidecarState>,
    method: axum::http::Method,
    Query(query): Query<HashMap<String, String>>,
) -> Result<axum::response::Response, axum::response::Response> {
    let resource_input = query.get("path").map(String::as_str).unwrap_or("");
    let root_input = query.get("root").map(String::as_str).unwrap_or("");

    let resource_rel =
        crate::normalize_workspace_relative_path(resource_input).map_err(|e| e.into_response())?;
    let preview_root = if root_input.trim().is_empty() {
        String::new()
    } else {
        crate::normalize_workspace_relative_path(root_input).map_err(|e| e.into_response())?
    };

    let head_only = method == axum::http::Method::HEAD;
    // CSP frame-ancestors is rewritten by the main process for the browser origin.
    // Sidecar still applies the shared MIME/cache/nosniff contract.
    let ws_path = sidecar_workspace_path(&state);
    crate::runtime::serve_local_preview_file(
        ws_path,
        &preview_root,
        &resource_rel,
        head_only,
        "http://127.0.0.1",
        None,
    )
    .map_err(|e| e.into_response())
}

async fn remote_sidecar_git_command(
    state: &RemoteSidecarState,
    args: &[&str],
) -> Result<std::process::Output, ApiError> {
    tokio::process::Command::new("git")
        .args(args)
        .current_dir(sidecar_workspace_path(state))
        .output()
        .await
        .map_err(|source| ApiError::internal(format!("remote git command failed: {source}")))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoteGitTargetQuery {
    worktree_path: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoteGitDiffQuery {
    path: Option<String>,
    worktree_path: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoteGitFileRequest {
    path: String,
    worktree_path: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoteGitCommitRequest {
    message: String,
    worktree_path: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct RemoteGitGenerateCommitMessageRequest {
    model_id: String,
    provider_id: String,
    worktree_path: Option<String>,
}

fn remote_sidecar_git_target(
    state: &RemoteSidecarState,
    worktree_path: Option<&str>,
) -> Result<PathBuf, ApiError> {
    // Use the same canonicalization and registered-worktree authorization as local Git routes.
    // A remote request may target the shared workspace or a Git worktree explicitly registered
    // with that repository; arbitrary paths, traversal, and symlink escapes are rejected.
    resolve_git_request_target(sidecar_workspace_path(state), worktree_path)
}

async fn remote_sidecar_git_status(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<RemoteGitTargetQuery>,
) -> Result<Json<GitStatusResponse>, axum::response::Response> {
    let target_path = remote_sidecar_git_target(&state, query.worktree_path.as_deref())
        .map_err(IntoResponse::into_response)?;
    Ok(Json(
        git_status_response(&target_path).map_err(IntoResponse::into_response)?,
    ))
}

async fn remote_sidecar_git_diff(
    State(state): State<RemoteSidecarState>,
    Query(query): Query<RemoteGitDiffQuery>,
) -> Result<Json<GitDiffResponse>, axum::response::Response> {
    let path = query
        .path
        .as_deref()
        .map(crate::normalize_workspace_relative_path)
        .transpose()
        .map_err(IntoResponse::into_response)?;
    let target_path = remote_sidecar_git_target(&state, query.worktree_path.as_deref())
        .map_err(IntoResponse::into_response)?;
    Ok(Json(
        git_diff_response(&target_path, path).map_err(IntoResponse::into_response)?,
    ))
}

