    #[tokio::test]
    async fn remote_chat_run_stream_replays_buffered_events_after_sequence() {
        let (state, _) = test_sidecar_state("/tmp/workspace".to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "run-1".to_string(),
            "chat-1".to_string(),
        );
        run_stream.record(0, json!({ "type": "start", "chatId": "chat-1" }));
        run_stream.record(
            1,
            json!({
                "type": "textDelta",
                "assistantMessageId": "assistant-1",
                "delta": "hello",
            }),
        );
        run_stream.record(2, json!({ "type": "streamEnd" }));
        run_stream.mark_finished();

        let response = remote_sidecar_chat_run_stream(
            State(state),
            AxumPath("run-1".to_string()),
            Query(HashMap::from([(
                "afterSequence".to_string(),
                "0".to_string(),
            )])),
        )
        .await
        .expect("run stream");
        let body = response.into_response().into_body();
        let bytes = tokio::time::timeout(
            Duration::from_millis(200),
            axum::body::to_bytes(body, usize::MAX),
        )
        .await
        .expect("SSE body should finish")
        .expect("SSE bytes");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        assert!(!text.contains("\"type\":\"start\""));
        assert!(text.contains("\"type\":\"textDelta\""));
        assert!(text.contains("\"type\":\"streamEnd\""));
    }

    #[tokio::test]
    async fn remote_chat_run_cancel_uses_broker_request_id() {
        let (state, mut broker_rx) = test_sidecar_state("/tmp/workspace".to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );
        run_stream.set_broker_request_id("broker-request-1".to_string());
        remote_sidecar_set_active_run(
            &state,
            RemoteActiveRunSummary {
                run_id: "remote-run-1".to_string(),
                chat_id: "chat-1".to_string(),
                last_sequence: Some(0),
                accepting_guidance: true,
                broker_status: "connected".to_string(),
                updated_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            },
        );
        while broker_rx.try_recv().is_ok() {}

        let response = remote_sidecar_chat_run_cancel(
            State(state.clone()),
            AxumPath("remote-run-1".to_string()),
        )
        .await
        .expect("cancel response")
        .0;
        assert_eq!(response["ok"], true);

        let cancel = broker_rx.recv().await.expect("cancel envelope");
        assert_eq!(cancel.message_type, "cancel");
        assert_eq!(cancel.id.as_deref(), Some("broker-request-1"));
        assert!(remote_sidecar_active_run_stream(&state, "remote-run-1").is_none());
        assert_eq!(state.active_run_count.load(Ordering::Relaxed), 0);
        assert!(run_stream.tool_token().is_cancelled());
        assert!(run_stream.is_cancel_requested());
    }

    #[test]
    fn remote_sidecar_runner_still_owns_turn_requires_matching_queued_run_identity() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database = WorkspaceDatabase::open_or_create(workspace.path()).expect("database");
        database.insert_chat("chat-1", "Chat").expect("chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "hello",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "running",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                            "runId": "remote-run-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("user");
        database
            .insert_message(NewMessage {
                id: "msg-assistant-1",
                chat_id: "chat-1",
                role: "assistant",
                content: "",
                sequence: 1,
                metadata_json: Some(r#"{"streamingState":"streaming"}"#),
            })
            .expect("assistant");

        assert!(remote_sidecar_runner_still_owns_turn(
            &database,
            "chat-1",
            "msg-assistant-1",
            "msg-user-1",
            "remote-run-1",
        ));

        remote_clear_message_queued_run(&mut database, "msg-user-1").expect("clear queued");
        assert!(
            !remote_sidecar_runner_still_owns_turn(
                &database,
                "chat-1",
                "msg-assistant-1",
                "msg-user-1",
                "remote-run-1",
            ),
            "cleared queuedRun must drop ownership"
        );

        // Replaced identity (edit rerun with new assistant id).
        database
            .update_message_metadata(
                "msg-user-1",
                &json!({
                    "queuedRun": {
                        "status": "running",
                        "userMessageId": "msg-user-1",
                        "assistantMessageId": "msg-assistant-new",
                        "runId": "remote-run-1",
                    }
                })
                .to_string(),
            )
            .expect("replace queued identity");
        assert!(!remote_sidecar_runner_still_owns_turn(
            &database,
            "chat-1",
            "msg-assistant-1",
            "msg-user-1",
            "remote-run-1",
        ));
        // New identity still owns even before the assistant row is inserted.
        assert!(remote_sidecar_runner_still_owns_turn(
            &database,
            "chat-1",
            "msg-assistant-new",
            "msg-user-1",
            "remote-run-1",
        ));
        assert!(!remote_sidecar_runner_still_owns_turn(
            &database,
            "chat-1",
            "msg-assistant-1",
            "msg-user-missing",
            "remote-run-1",
        ));
    }

