    #[test]
    fn broker_llm_cancellation_audit_contract_is_request_kind_and_signal_aware() {
        let without_wire = broker_llm_cancellation_audit_outcome(
            BROKER_DEFAULT_LLM_REQUEST_KIND,
            true,
            None,
            "broker request cancelled",
        );
        assert_eq!(without_wire.final_state, "cancelled");
        assert_eq!(without_wire.response_body_json, None);

        let captured =
            r#"{"format":"provider_final_response_v1","version":1,"partial":true}"#.to_string();
        let detailed = broker_llm_cancellation_audit_outcome(
            BROKER_DEFAULT_LLM_REQUEST_KIND,
            true,
            Some(captured.clone()),
            "broker request cancelled",
        );
        assert_eq!(detailed.final_state, "cancelled");
        assert_eq!(
            detailed.response_body_json.as_deref(),
            Some(captured.as_str())
        );

        for request_kind in [
            BROKER_PROMPT_HOOK_REQUEST_KIND,
            BROKER_CONTEXT_COMPRESSION_REQUEST_KIND,
            GIT_COMMIT_MESSAGE_REQUEST_KIND,
            LLM_REQUEST_KIND_WORKSPACE_SPEC_GENERATION,
            LLM_REQUEST_KIND_WORKSPACE_SPEC_UPDATE,
            LLM_REQUEST_KIND_WORKSPACE_SPEC_COMPACTION,
            LLM_REQUEST_KIND_WORKSPACE_SPEC_UPDATE_COMPACTION,
        ] {
            let internal = broker_llm_cancellation_audit_outcome(
                request_kind,
                true,
                None,
                "broker request cancelled",
            );
            assert_eq!(internal.final_state, "failed");
            assert_eq!(internal.response_body_json, None);
        }

        let not_explicit = broker_llm_cancellation_audit_outcome(
            BROKER_DEFAULT_LLM_REQUEST_KIND,
            false,
            None,
            "stream error text says cancelled",
        );
        assert_eq!(not_explicit.final_state, "failed");
        assert_eq!(not_explicit.response_body_json, None);
    }

    #[test]
    fn concurrent_broker_audit_finish_is_idempotent_and_atomic() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let context = BrokerLlmAuditContext {
            audit_path: workspace.path().to_path_buf(),
            workspace_id: "remote-ws".to_string(),
            chat_id: Some("chat-1".to_string()),
            chat_title: Some("Remote chat".to_string()),
            request_id: "request-concurrent-finish".to_string(),
            request_kind: BROKER_DEFAULT_LLM_REQUEST_KIND.to_string(),
        };
        let writer = broker_llm_audit_writer_for_test(
            &context,
            "provider-1",
            "model-1",
            None,
            "2026-07-16T00:00:00Z",
        );
        let barrier = Arc::new(std::sync::Barrier::new(2));
        let threads = (0..2)
            .map(|_| {
                let writer = writer.clone();
                let barrier = Arc::clone(&barrier);
                std::thread::spawn(move || {
                    let events = [BrokerLlmAuditEvent {
                        event_at: "2026-07-16T00:00:01Z".to_string(),
                        event_type: "text_delta".to_string(),
                        normalized_event: json!({ "type": "text_delta", "text": "hello" }),
                    }];
                    barrier.wait();
                    writer.finish(
                        BrokerLlmAuditOutcome {
                            final_state: "succeeded",
                            first_token_at: Some("2026-07-16T00:00:00.100Z"),
                            completed_at: "2026-07-16T00:00:02Z",
                            usage: None,
                            first_token_latency_ms: Some(100),
                            total_latency_ms: 2000,
                            status_code: Some(200),
                            response_body_json: None,
                        },
                        &events,
                    )
                })
            })
            .collect::<Vec<_>>();

        for thread in threads {
            thread
                .join()
                .expect("broker audit writer thread")
                .expect("concurrent broker audit finish");
        }

        let database = WorkspaceDatabase::open_or_create(workspace.path()).expect("audit db");
        let request = database
            .llm_request("request-concurrent-finish")
            .expect("request lookup")
            .expect("request row");
        assert_eq!(request.final_state, "succeeded");
        assert_eq!(
            database
                .llm_request_events("request-concurrent-finish")
                .expect("request events")
                .len(),
            1
        );
    }

    #[test]
    fn finish_broker_llm_audit_persists_cancelled_null_detail_and_captured_v1_responses() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let cases = [
            ("cancel-null-detail", None, None, false, false),
            (
                "cancel-versioned",
                Some(foco_providers::ProviderFinalResponseDump::failed(
                    "broker request cancelled",
                    None,
                    false,
                )),
                Some(false),
                true,
                false,
            ),
            (
                "cancel-partial",
                Some(foco_providers::ProviderFinalResponseDump::failed(
                    "broker request cancelled",
                    None,
                    true,
                )),
                Some(true),
                true,
                true,
            ),
        ];

        for (request_id, captured_dump, expected_partial, capture_details, has_first_token) in cases
        {
            let context = BrokerLlmAuditContext {
                audit_path: workspace.path().to_path_buf(),
                workspace_id: "remote-ws".to_string(),
                chat_id: Some("chat-1".to_string()),
                chat_title: Some("Remote chat".to_string()),
                request_id: request_id.to_string(),
                request_kind: BROKER_DEFAULT_LLM_REQUEST_KIND.to_string(),
            };
            let audit_writer = broker_llm_audit_writer_for_test(
                &context,
                "provider-1",
                "model-1",
                None,
                "2026-07-12T00:00:00Z",
            );
            let capture = ProviderAuditCapture::new(workspace.path(), request_id, capture_details);
            let captured_response_body_json = captured_dump.as_ref().map(|dump| {
                capture
                    .response_json(Some(dump))
                    .expect("serialize captured response")
                    .expect("captured response detail")
            });
            let cancel_audit = broker_llm_cancellation_audit_outcome(
                BROKER_DEFAULT_LLM_REQUEST_KIND,
                true,
                captured_response_body_json,
                "broker request cancelled",
            );
            finish_broker_llm_audit(
                Some(&audit_writer),
                BrokerLlmAuditOutcome {
                    final_state: cancel_audit.final_state,
                    first_token_at: has_first_token.then_some("2026-07-12T00:00:01Z"),
                    completed_at: "2026-07-12T00:00:02Z",
                    usage: None,
                    first_token_latency_ms: has_first_token.then_some(1000),
                    total_latency_ms: 2000,
                    status_code: None,
                    response_body_json: cancel_audit.response_body_json.as_deref(),
                },
                &[],
            );

            let request = WorkspaceDatabase::open_or_create(workspace.path())
                .expect("audit db")
                .llm_request(request_id)
                .expect("request lookup")
                .expect("persisted request");
            assert_eq!(request.final_state, "cancelled");
            if let Some(expected_partial) = expected_partial {
                let response = serde_json::from_str::<Value>(
                    request
                        .response_body_json
                        .as_deref()
                        .expect("persisted cancelled response"),
                )
                .expect("valid cancelled response JSON");
                assert_eq!(response["format"], "provider_final_response_v1");
                assert_eq!(response["state"], "failed");
                assert_eq!(response["partial"], expected_partial);
            } else {
                assert_eq!(request.response_body_json, None);
            }
        }
    }

    #[test]
    fn broker_non_cancel_failures_remain_failed() {
        for message in [
            "provider request timed out",
            "remote sidecar disconnected",
            "provider stream failed",
            "Runtime progress guard detected a repeated reasoning loop",
        ] {
            let outcome = broker_llm_cancellation_audit_outcome(
                BROKER_DEFAULT_LLM_REQUEST_KIND,
                false,
                None,
                message,
            );
            assert_eq!(outcome.final_state, "failed", "message: {message}");
            assert_eq!(outcome.response_body_json, None, "message: {message}");
        }
    }

    #[test]
    fn remote_sidecar_broker_error_audit_contract_uses_only_structured_cancel_code() {
        let cancelled = remote_sidecar_broker_error_audit_outcome(
            &json!({ "code": "cancelled", "message": "broker request cancelled" }),
            "broker request cancelled",
        );
        assert_eq!(cancelled.final_state, "cancelled");

        for payload in [
            json!({ "code": "provider_error", "message": "provider said cancelled" }),
            json!({ "message": "broker request cancelled" }),
        ] {
            let failed = remote_sidecar_broker_error_audit_outcome(
                &payload,
                payload["message"].as_str().expect("error message"),
            );
            assert_eq!(failed.final_state, "failed");
        }
    }

