    #[test]
    fn remote_run_deactivation_hides_the_run_before_its_terminal_stream_events() {
        let (state, _) = test_sidecar_state("/tmp/workspace".to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );
        remote_sidecar_set_active_run(
            &state,
            RemoteActiveRunSummary {
                run_id: "remote-run-1".to_string(),
                chat_id: "chat-1".to_string(),
                last_sequence: Some(0),
                accepting_guidance: true,
                broker_status: "connected".to_string(),
                updated_at: "2026-07-19T00:00:00Z".to_string(),
            },
        );

        let registration = remote_sidecar_deactivate_active_run(&state, "remote-run-1")
            .expect("active registration");
        assert!(remote_sidecar_active_run_stream(&state, "remote-run-1").is_none());
        assert_eq!(state.active_run_count.load(Ordering::Relaxed), 0);
        assert!(!run_stream.is_finished());

        registration
            .run_stream
            .record(1, json!({ "type": "streamEnd" }));
        registration.run_stream.mark_finished();
        assert!(run_stream.is_finished());
    }

    #[tokio::test]
    async fn remote_second_turn_starts_after_terminal_deactivation_without_old_owner_cleanup() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        seed_remote_queued_chat(
            &mut database,
            "chat-two-turns",
            "user-turn-1",
            "assistant-turn-1",
        );
        drop(database);
        let (state, _) = test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);

        let (first_run_id, first_stream) = match remote_sidecar_reserve_active_run(
            &state,
            "chat-two-turns".to_string(),
            "user-turn-1".to_string(),
            "assistant-turn-1".to_string(),
            None,
        )
        .expect("reserve first turn")
        {
            RemoteRunReservation::Started { run_id, run_stream } => (run_id, run_stream),
            RemoteRunReservation::Existing { .. } => panic!("first turn must reserve a new run"),
        };
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .claim_remote_queued_run(
                "chat-two-turns",
                "user-turn-1",
                "assistant-turn-1",
                &first_run_id,
            )
            .expect("claim first turn");
        remote_sidecar_set_active_run(
            &state,
            RemoteActiveRunSummary {
                run_id: first_run_id.clone(),
                chat_id: "chat-two-turns".to_string(),
                last_sequence: Some(0),
                accepting_guidance: true,
                broker_status: "connected".to_string(),
                updated_at: "2026-07-19T00:00:00Z".to_string(),
            },
        );

        let terminal_stream = remote_sidecar_deactivate_active_run(&state, &first_run_id)
            .expect("first active registration")
            .run_stream;
        assert_eq!(state.active_run_count.load(Ordering::Relaxed), 0);
        assert!(remote_sidecar_active_run_stream(&state, &first_run_id).is_none());
        assert_eq!(
            database
                .clear_remote_queued_run_if_owned(
                    "chat-two-turns",
                    "user-turn-1",
                    "assistant-turn-1",
                    &first_run_id,
                )
                .expect("clear completed first turn"),
            foco_store::workspace::RemoteQueuedRunClearOutcome::Cleared
        );
        terminal_stream.record(1, json!({ "type": "complete" }));
        terminal_stream.record(2, json!({ "type": "streamEnd" }));
        terminal_stream.mark_finished();
        assert_eq!(first_stream.snapshot_after(-1).len(), 2);

        database
            .insert_message(NewMessage {
                id: "user-turn-2",
                chat_id: "chat-two-turns",
                role: "user",
                content: "next task",
                sequence: 2,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "user-turn-2",
                            "assistantMessageId": "assistant-turn-2",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert second user");
        database
            .insert_message(NewMessage {
                id: "assistant-turn-2",
                chat_id: "chat-two-turns",
                role: "assistant",
                content: "",
                sequence: 3,
                metadata_json: Some(r#"{"streamingState":"streaming"}"#),
            })
            .expect("insert second assistant");
        let plan_task_id = AgentTaskId::new("agent-task-two-turns").expect("plan task id");
        let (second_run_id, second_stream) = match remote_sidecar_reserve_active_run(
            &state,
            "chat-two-turns".to_string(),
            "user-turn-2".to_string(),
            "assistant-turn-2".to_string(),
            Some(plan_task_id),
        )
        .expect("reserve second turn")
        {
            RemoteRunReservation::Started { run_id, run_stream } => (run_id, run_stream),
            RemoteRunReservation::Existing { .. } => panic!("second turn must reserve a new run"),
        };
        assert_ne!(first_run_id, second_run_id);
        database
            .claim_remote_queued_run(
                "chat-two-turns",
                "user-turn-2",
                "assistant-turn-2",
                &second_run_id,
            )
            .expect("claim second turn");
        remote_sidecar_set_active_run(
            &state,
            RemoteActiveRunSummary {
                run_id: second_run_id.clone(),
                chat_id: "chat-two-turns".to_string(),
                last_sequence: Some(0),
                accepting_guidance: true,
                broker_status: "connected".to_string(),
                updated_at: "2026-07-19T00:00:01Z".to_string(),
            },
        );

        let reconnect = remote_sidecar_chat_run_stream(
            State(state.clone()),
            AxumPath(second_run_id.clone()),
            Query(HashMap::new()),
        )
        .await
        .expect("second turn reconnect stream");
        drop(reconnect);
        let registered_second_stream =
            remote_sidecar_active_run_stream(&state, &second_run_id).expect("second stream");
        assert!(Arc::ptr_eq(
            &second_stream.events,
            &registered_second_stream.events
        ));

        assert_eq!(
            database
                .clear_remote_queued_run_if_owned(
                    "chat-two-turns",
                    "user-turn-1",
                    "assistant-turn-1",
                    &first_run_id,
                )
                .expect("late first-run cleanup"),
            foco_store::workspace::RemoteQueuedRunClearOutcome::NotOwned
        );
        let second_user = database
            .message("user-turn-2")
            .expect("second user lookup")
            .expect("second user message");
        let metadata: Value =
            serde_json::from_str(&second_user.metadata_json).expect("second metadata");
        assert_eq!(metadata["queuedRun"]["runId"], second_run_id);
        assert_eq!(metadata["queuedRun"]["status"], "running");

        remote_sidecar_cancel_active_run(&state, &second_run_id, false, true);
    }

    #[tokio::test]
    async fn remote_run_cleanup_guard_is_idempotent_after_normal_finish() {
        let (state, mut broker_rx) = test_sidecar_state("/tmp/workspace".to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );
        run_stream.set_broker_request_id("broker-request-1".to_string());
        let (tx, _rx) = mpsc::unbounded_channel();
        state
            .broker_pending
            .lock()
            .await
            .insert("broker-request-1".to_string(), tx);
        remote_sidecar_set_active_run(
            &state,
            RemoteActiveRunSummary {
                run_id: "remote-run-1".to_string(),
                chat_id: "chat-1".to_string(),
                last_sequence: Some(0),
                accepting_guidance: true,
                broker_status: "connected".to_string(),
                updated_at: Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
            },
        );
        while broker_rx.try_recv().is_ok() {}

        remote_sidecar_finish_active_run(&state, "remote-run-1");
        assert!(remote_sidecar_active_run_stream(&state, "remote-run-1").is_none());

        {
            let _guard = RemoteRunCleanupGuard::new(state.clone(), "remote-run-1".to_string());
        }
        let mut saw_cancel = false;
        while let Ok(envelope) = broker_rx.try_recv() {
            if envelope.message_type == "cancel" {
                saw_cancel = true;
            }
        }
        assert!(
            !saw_cancel,
            "cleanup after normal finish must not re-cancel broker"
        );
        assert!(
            state
                .broker_pending
                .lock()
                .await
                .contains_key("broker-request-1")
        );
    }

    #[tokio::test]
    async fn remote_sidecar_chat_stream_flushes_broker_events_to_initial_sse() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "hello",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);

        let response = remote_sidecar_chat_stream(
            State(state.clone()),
            Json(json!({
                "chatId": "chat-1",
                "queuedUserMessageId": "msg-user-1",
                "visibleAssistantMessageId": "msg-assistant-1",
                "modelId": "model-1",
                "providerId": "provider-1",
            })),
        )
        .await
        .expect("SSE response");

        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let request = loop {
                let envelope = broker_rx.recv().await.expect("broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            assert_eq!(request.method.as_deref(), Some("llm.stream"));
            let id = request.id.clone().expect("request id");
            let pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&id)
                .cloned()
                .expect("pending response channel");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "textDelta",
                        "delta": "hello remote",
                    }),
                    timestamp: None,
                })
                .expect("send text delta");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(id),
                    method: None,
                    payload: json!({
                        "usage": {
                            "inputTokens": 4,
                            "outputTokens": 2,
                            "cacheReadTokens": null,
                            "cacheWriteTokens": null,
                        },
                        "toolCalls": [],
                    }),
                    timestamp: None,
                })
                .expect("send completion");
        });

        let bytes = tokio::time::timeout(
            Duration::from_secs(1),
            axum::body::to_bytes(response.into_response().into_body(), usize::MAX),
        )
        .await
        .expect("initial SSE body should finish")
        .expect("SSE bytes");
        broker.await.expect("broker task");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        assert!(text.contains("\"type\":\"start\""));
        assert!(text.contains("\"type\":\"connecting\""));
        assert!(text.contains("\"type\":\"textDelta\""));
        assert!(text.contains("hello remote"));
        assert!(text.contains("\"type\":\"complete\""));
        assert!(text.contains("\"totalLatencyMs\":"));
        assert!(!text.contains("\"totalLatencyMs\":null"));
        assert!(text.contains("\"firstTokenLatencyMs\":"));
        assert!(!text.contains("\"firstTokenLatencyMs\":null"));
        assert!(text.contains("\"outputTokens\":2"));
        assert!(text.contains("\"type\":\"streamEnd\""));

        let database = WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant message lookup")
            .expect("assistant message");
        let metadata =
            serde_json::from_str::<Value>(&assistant.metadata_json).expect("assistant metadata");
        assert!(metadata["metrics"]["totalLatencyMs"].as_i64().unwrap_or(0) > 0);
        assert!(metadata["metrics"]["firstTokenLatencyMs"].is_number());
        assert_eq!(metadata["metrics"]["outputTokens"], 2);
        let audit = database
            .llm_request_audit_rows(LlmRequestAuditFilters {
                chat_id: Some("chat-1"),
                ..LlmRequestAuditFilters::default()
            })
            .expect("audit rows")
            .into_iter()
            .next()
            .expect("audit row");
        assert_eq!(audit.output_tokens, Some(2));
        assert!(audit.first_token_latency_ms.is_some());
        assert!(audit.total_latency_ms.unwrap_or(0) > 0);
    }

    #[tokio::test]
    async fn remote_sidecar_chat_stream_aggregates_tool_followup_metrics() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        fs::write(
            workspace.path().join("Cargo.toml"),
            "[package]\nname = \"fixture\"\n",
        )
        .expect("write tool fixture");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "read Cargo.toml",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);

        let response = remote_sidecar_chat_stream(
            State(state.clone()),
            Json(json!({
                "chatId": "chat-1",
                "queuedUserMessageId": "msg-user-1",
                "visibleAssistantMessageId": "msg-assistant-1",
                "modelId": "model-1",
                "providerId": "provider-1",
            })),
        )
        .await
        .expect("SSE response");

        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let first_request = loop {
                let envelope = broker_rx.recv().await.expect("first broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            let first_id = first_request.id.expect("first request id");
            let first_pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&first_id)
                .cloned()
                .expect("first pending response channel");
            first_pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(first_id.clone()),
                    method: None,
                    payload: json!({
                        "usage": { "inputTokens": 4, "outputTokens": 2 },
                        "toolCalls": [{
                            "callId": "call-1",
                            "name": "read_file",
                            "arguments": {
                                "path": "Cargo.toml",
                                "startLine": null,
                                "endLine": null,
                                "timeoutMs": null
                            }
                        }],
                    }),
                    timestamp: None,
                })
                .expect("send first response");

            let second_request = loop {
                let envelope = broker_rx.recv().await.expect("second broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            assert!(
                second_request.payload["request"]["messages"]
                    .as_array()
                    .expect("followup messages")
                    .iter()
                    .any(|message| message["role"] == "tool")
            );
            let second_id = second_request.id.expect("second request id");
            let second_pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&second_id)
                .cloned()
                .expect("second pending response channel");
            second_pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(second_id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "textDelta",
                        "delta": "done",
                    }),
                    timestamp: None,
                })
                .expect("send final text delta");
            second_pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(second_id.clone()),
                    method: None,
                    payload: json!({
                        "usage": { "inputTokens": 6, "outputTokens": 3 },
                        "toolCalls": [],
                    }),
                    timestamp: None,
                })
                .expect("send final response");
            (first_id, second_id)
        });

        let bytes = tokio::time::timeout(
            Duration::from_secs(10),
            axum::body::to_bytes(response.into_response().into_body(), usize::MAX),
        )
        .await
        .expect("tool followup SSE body should finish")
        .expect("SSE bytes");
        let (first_broker_request_id, second_broker_request_id) =
            broker.await.expect("broker task");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        assert!(text.contains("\"type\":\"toolResult\""));
        assert!(text.contains("\"type\":\"complete\""));
        assert!(text.contains("\"outputTokens\":5"));
        assert!(!text.contains("\"totalLatencyMs\":null"));

        let database = WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant message lookup")
            .expect("assistant message");
        let metadata =
            serde_json::from_str::<Value>(&assistant.metadata_json).expect("assistant metadata");
        let total_latency_ms = metadata["metrics"]["totalLatencyMs"]
            .as_i64()
            .expect("message total latency");
        assert!(total_latency_ms > 0);
        assert!(metadata["metrics"]["firstTokenLatencyMs"].is_number());
        assert_eq!(metadata["metrics"]["outputTokens"], 5);
        assert_eq!(
            metadata["metrics"]["llmRequestIds"],
            json!([&first_broker_request_id, &second_broker_request_id])
        );

        let audit_rows = database
            .llm_request_audit_rows(LlmRequestAuditFilters {
                chat_id: Some("chat-1"),
                ..LlmRequestAuditFilters::default()
            })
            .expect("audit rows");
        assert_eq!(audit_rows.len(), 2);

        let first_audit = database
            .llm_request(&first_broker_request_id)
            .expect("first audit lookup")
            .expect("first broker audit row");
        assert_eq!(first_audit.input_tokens, Some(4));
        assert_eq!(first_audit.output_tokens, Some(2));
        assert!(first_audit.first_token_latency_ms.is_some());
        assert!(first_audit.total_latency_ms.unwrap_or_default() > 0);

        let second_audit = database
            .llm_request(&second_broker_request_id)
            .expect("second audit lookup")
            .expect("second broker audit row");
        assert_eq!(second_audit.input_tokens, Some(6));
        assert_eq!(second_audit.output_tokens, Some(3));
        assert!(second_audit.first_token_latency_ms.is_some());
        assert!(second_audit.total_latency_ms.unwrap_or_default() > 0);
    }

    #[tokio::test]
    async fn remote_sidecar_cancelled_broker_error_persists_cancelled_null_detail_mirror() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        let (state, mut broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );

        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let request = loop {
                let envelope = broker_rx.recv().await.expect("broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            let id = request.id.expect("request id");
            let pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&id)
                .cloned()
                .expect("pending response channel");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "route",
                        "providerId": "provider-current",
                        "modelId": "model-1",
                    }),
                    timestamp: None,
                })
                .expect("send route confirmation");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "error".to_string(),
                    id: Some(id),
                    method: None,
                    payload: json!({
                        "code": "cancelled",
                        "message": "broker request cancelled",
                    }),
                    timestamp: None,
                })
                .expect("send cancelled broker error");
        });

        let mut text = String::new();
        let mut reasoning = String::new();
        let mut run_metrics = RemoteSidecarRunMetrics::new();
        let mut sequence = 0_i64;
        let result = remote_sidecar_run_broker_llm_turn(
            &state,
            &run_stream,
            "broker-request-1",
            json!({ "providerId": "provider-legacy", "modelId": "model-1" }),
            "remote-run-1",
            "chat-1",
            "msg-assistant-1",
            "msg-user-1",
            "provider-legacy",
            "model-1",
            &mut text,
            &mut reasoning,
            &mut run_metrics,
            &mut sequence,
            &[],
            &[],
            0,
            0,
        )
        .await;
        broker.await.expect("broker task");

        assert!(result.is_err());
        let audit = database
            .llm_request("broker-request-1")
            .expect("sidecar audit lookup")
            .expect("sidecar audit exists");
        assert_eq!(audit.request_kind, BROKER_DEFAULT_LLM_REQUEST_KIND);
        assert_eq!(audit.final_state, "cancelled");
        assert_eq!(audit.provider_id, "provider-current");
        assert_eq!(audit.response_body_json, None);
        let events = run_stream.snapshot_after(-1);
        assert_eq!(
            events
                .iter()
                .rev()
                .take(2)
                .map(|(_, event)| event["type"].as_str().unwrap_or_default())
                .collect::<Vec<_>>(),
            vec!["streamEnd", "error"]
        );
    }

    #[tokio::test]
    async fn remote_sidecar_reasoning_loop_guard_cancels_broker_and_persists_partial_failure() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "hello",
                sequence: 0,
                metadata_json: Some("{}"),
            })
            .expect("insert user message");
        database
            .insert_message(NewMessage {
                id: "msg-assistant-1",
                chat_id: "chat-1",
                role: "assistant",
                content: "",
                sequence: 1,
                metadata_json: Some("{}"),
            })
            .expect("insert assistant placeholder");
        let (state, mut broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );
        run_stream.set_broker_request_id("broker-request-1".to_string());

        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let request = loop {
                let envelope = broker_rx.recv().await.expect("broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            let id = request.id.clone().expect("request id");
            let pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&id)
                .cloned()
                .expect("pending response channel");
            let reasoning_period =
                "Inspect the premise, compare the evidence, and restart the same analysis. ";
            for _ in 0..24 {
                pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "stream".to_string(),
                        id: Some(id.clone()),
                        method: None,
                        payload: json!({
                            "kind": "reasoningDelta",
                            "delta": reasoning_period,
                        }),
                        timestamp: None,
                    })
                    .expect("send repeated reasoning delta");
            }
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "reasoningDelta",
                        "delta": "SENTINEL_AFTER_LOOP_GUARD",
                    }),
                    timestamp: None,
                })
                .expect("send post-loop sentinel");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "usage": { "inputTokens": 8, "outputTokens": 80 },
                        "toolCalls": [],
                    }),
                    timestamp: None,
                })
                .expect("send unreachable response");

            loop {
                let envelope = broker_rx.recv().await.expect("broker cancel");
                if envelope.message_type == "cancel" {
                    assert_eq!(envelope.id.as_deref(), Some(id.as_str()));
                    break;
                }
            }
        });

        let mut text = String::new();
        let mut reasoning = String::new();
        let mut run_metrics = RemoteSidecarRunMetrics::new();
        let mut sequence = 0_i64;
        let result = remote_sidecar_run_broker_llm_turn(
            &state,
            &run_stream,
            "broker-request-1",
            json!({ "providerId": "provider-1", "modelId": "model-1" }),
            "remote-run-1",
            "chat-1",
            "msg-assistant-1",
            "msg-user-1",
            "provider-1",
            "model-1",
            &mut text,
            &mut reasoning,
            &mut run_metrics,
            &mut sequence,
            &[],
            &[],
            0,
            0,
        )
        .await;
        broker.await.expect("broker task");

        // Broker-turn helper only cancels the RPC + partial audit; outer loop owns recovery/error.
        let interrupted = match result {
            Ok(RemoteSidecarBrokerLlmTurnOutcome::ReasoningLoopInterrupted {
                message,
                turn_llm_request_id,
                ..
            }) => {
                assert!(message.contains("Runtime progress guard"));
                assert!(message.contains("repeated reasoning loop"));
                assert!(message.contains("Partial reasoning was preserved"));
                assert_eq!(turn_llm_request_id, "broker-request-1");
                true
            }
            other => {
                panic!("expected ReasoningLoopInterrupted, got {other:?}");
            }
        };
        assert!(interrupted);
        assert!(text.is_empty());
        assert!(!reasoning.is_empty());
        assert!(!reasoning.contains("SENTINEL_AFTER_LOOP_GUARD"));
        let events = run_stream.snapshot_after(-1);
        assert!(
            events
                .iter()
                .all(|(_, event)| event["type"] != "error" && event["type"] != "streamEnd"),
            "broker turn must not emit terminal error/streamEnd on loop guard: {events:?}"
        );
        assert!(
            events
                .iter()
                .any(|(_, event)| event["type"] == "reasoningDelta")
        );

        // Assistant placeholder is not finalized by the broker-turn helper alone.
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant message lookup")
            .expect("assistant message");
        assert_eq!(assistant.content, "");
        let audit = database
            .llm_request("broker-request-1")
            .expect("sidecar audit lookup")
            .expect("sidecar audit exists");
        assert_eq!(audit.request_kind, BROKER_DEFAULT_LLM_REQUEST_KIND);
        assert_eq!(audit.final_state, "failed");
        // Sidecar mirror: structured columns only; partial/error stay in SSE + message metadata.
        assert_eq!(audit.request_body_json, None);
        assert_eq!(audit.response_body_json, None);
    }

    #[tokio::test]
    async fn remote_sidecar_chat_stream_reasoning_loop_auto_recovers_with_second_broker_rpc() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "trigger loop then recover",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);

        let response = remote_sidecar_chat_stream(
            State(state.clone()),
            Json(json!({
                "chatId": "chat-1",
                "queuedUserMessageId": "msg-user-1",
                "visibleAssistantMessageId": "msg-assistant-1",
                "modelId": "model-1",
                "providerId": "provider-1",
            })),
        )
        .await
        .expect("SSE response");

        let broker_state = state.clone();
        let broker =
            tokio::spawn(async move {
                let first_request = loop {
                    let envelope = broker_rx.recv().await.expect("first broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let first_id = first_request.id.clone().expect("first request id");
                let first_pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&first_id)
                    .cloned()
                    .expect("first pending response channel");
                let reasoning_period =
                    "Inspect the premise, compare the evidence, and restart the same analysis. ";
                for _ in 0..24 {
                    if first_pending
                        .send(ControlEnvelope {
                            version: 1,
                            message_type: "stream".to_string(),
                            id: Some(first_id.clone()),
                            method: None,
                            payload: json!({
                                "kind": "reasoningDelta",
                                "delta": reasoning_period,
                            }),
                            timestamp: None,
                        })
                        .is_err()
                    {
                        // Consumer may cancel and drop the channel once the loop is detected.
                        break;
                    }
                }
                loop {
                    let envelope = broker_rx.recv().await.expect("first cancel");
                    if envelope.message_type == "cancel" {
                        assert_eq!(envelope.id.as_deref(), Some(first_id.as_str()));
                        break;
                    }
                }

                let second_request = loop {
                    let envelope = broker_rx.recv().await.expect("second broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let second_messages = second_request.payload["request"]["messages"]
                    .as_array()
                    .expect("second request messages")
                    .clone();
                assert!(
                    second_messages.iter().any(|message| {
                        message["role"] == "assistant"
                            && (message
                                .get("reasoning")
                                .and_then(Value::as_str)
                                .is_some_and(|value| !value.is_empty())
                                || message
                                    .get("content")
                                    .and_then(Value::as_str)
                                    .is_some_and(|value| !value.is_empty()))
                    }),
                    "second RPC must include partial assistant: {second_messages:?}"
                );
                assert!(
                    second_messages.iter().any(|message| {
                        message["role"] == "user"
                            && message.get("content").and_then(Value::as_str).is_some_and(
                                |content| content.contains(REASONING_LOOP_RECOVERY_USER_TEXT),
                            )
                    }),
                    "second RPC must include fixed recovery user text: {second_messages:?}"
                );
                let second_id = second_request.id.expect("second request id");
                let second_pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&second_id)
                    .cloned()
                    .expect("second pending response channel");
                second_pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "stream".to_string(),
                        id: Some(second_id.clone()),
                        method: None,
                        payload: json!({
                            "kind": "textDelta",
                            "delta": "Recovered after reasoning loop",
                        }),
                        timestamp: None,
                    })
                    .expect("send recovery text");
                second_pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "response".to_string(),
                        id: Some(second_id.clone()),
                        method: None,
                        payload: json!({
                            "usage": { "inputTokens": 6, "outputTokens": 3 },
                            "toolCalls": [],
                        }),
                        timestamp: None,
                    })
                    .expect("send recovery response");
                (first_id, second_id)
            });

        let bytes = tokio::time::timeout(
            Duration::from_secs(5),
            axum::body::to_bytes(response.into_response().into_body(), usize::MAX),
        )
        .await
        .expect("recovery SSE body should finish")
        .expect("SSE bytes");
        let (first_broker_request_id, second_broker_request_id) =
            broker.await.expect("broker task");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        assert!(text.contains("\"type\":\"guidanceApplied\""));
        assert!(text.contains(REASONING_LOOP_RECOVERY_USER_TEXT));
        assert!(text.contains("\"type\":\"complete\""));
        assert!(text.contains("Recovered after reasoning loop"));
        assert!(!text.contains("\"type\":\"error\""));
        assert!(
            text.contains(&format!("\"llmRequestId\":\"{first_broker_request_id}\"")),
            "SSE streamAttemptStart must include first broker id: {text}"
        );
        assert!(
            text.contains(&format!("\"llmRequestId\":\"{second_broker_request_id}\"")),
            "SSE streamAttemptStart must include second broker id: {text}"
        );

        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant message lookup")
            .expect("assistant message");
        assert_eq!(assistant.content, "Recovered after reasoning loop");
        let metadata =
            serde_json::from_str::<Value>(&assistant.metadata_json).expect("assistant metadata");
        let parts = metadata
            .get("parts")
            .and_then(Value::as_array)
            .expect("assistant parts");
        assert!(
            parts.iter().any(|part| {
                part.get("type").and_then(Value::as_str) == Some("userInterruption")
                    && part.get("content").and_then(Value::as_str)
                        == Some(REASONING_LOOP_RECOVERY_USER_TEXT)
                    && part.get("source").and_then(Value::as_str)
                        == Some(REASONING_LOOP_GUARD_SOURCE)
            }),
            "final parts must include userInterruption: {parts:?}"
        );

        let first_audit = database
            .llm_request(&first_broker_request_id)
            .expect("first audit lookup")
            .expect("first broker audit");
        assert_eq!(first_audit.final_state, "failed");
        let second_audit = database
            .llm_request(&second_broker_request_id)
            .expect("second audit lookup")
            .expect("second broker audit");
        assert_eq!(second_audit.final_state, "succeeded");

        let durable_events = database
            .history_run_events_for_chat_messages("chat-1", &["msg-assistant-1".to_string()])
            .expect("run events");
        assert!(
            durable_events
                .iter()
                .any(|event| event.event_type == "guidance_applied"),
            "guidance_applied must be durable for rematerialize"
        );

        let history = remote_sidecar_chat_messages_for_request(
            &database,
            "chat-1",
            None,
            &std::collections::HashSet::new(),
        )
        .expect("history for request");
        assert!(
            history.messages.iter().any(|message| {
                message.role == NeutralChatRole::User
                    && message.content.contains(REASONING_LOOP_RECOVERY_USER_TEXT)
            }),
            "prompt history should replay interruption as user: {:?}",
            history.messages
        );
        let mut saw_partial_assistant = false;
        let mut saw_recovery_user = false;
        let mut saw_final_assistant = false;
        for message in &history.messages {
            match message.role {
                NeutralChatRole::Assistant
                    if !message.content.is_empty()
                        || message
                            .reasoning
                            .as_ref()
                            .is_some_and(|value| !value.is_empty()) =>
                {
                    if saw_recovery_user {
                        saw_final_assistant = true;
                    } else {
                        saw_partial_assistant = true;
                    }
                }
                NeutralChatRole::User
                    if message.content.contains(REASONING_LOOP_RECOVERY_USER_TEXT) =>
                {
                    saw_recovery_user = true;
                }
                _ => {}
            }
        }
        assert!(
            saw_partial_assistant && saw_recovery_user && saw_final_assistant,
            "expected Assistant → User → Assistant boundary in history: {:?}",
            history.messages
        );

        // Strip parts so reconnect/history rematerialize rebuilds interruption from run_events.
        // Remote stream only durable-persists guidance_applied (not every reasoningDelta).
        // Rematerialize must rebuild interruption and best-effort fold message content/reasoning.
        let mut stripped = serde_json::from_str::<Value>(&assistant.metadata_json)
            .expect("assistant metadata for strip");
        if let Some(object) = stripped.as_object_mut() {
            object.remove("parts");
            object.remove("partsSource");
            object.remove("partsVersion");
        }
        database
            .update_message_metadata("msg-assistant-1", &stripped.to_string())
            .expect("strip parts");
        let tool_calls = database.tool_calls_for_chat("chat-1").expect("tool calls");
        let mut messages = database
            .messages_for_chat_page("chat-1", None, 50)
            .expect("messages");
        remote_materialize_missing_assistant_parts(
            &mut database,
            "chat-1",
            &mut messages,
            &tool_calls,
        )
        .expect("rematerialize after strip");
        let rematerialized = messages
            .iter()
            .find(|message| message.id == "msg-assistant-1")
            .expect("assistant after rematerialize");
        let rematerialized_meta: Value =
            serde_json::from_str(&rematerialized.metadata_json).expect("rematerialized metadata");
        let rematerialized_parts = rematerialized_meta
            .get("parts")
            .and_then(Value::as_array)
            .expect("rematerialized parts");
        assert!(
            rematerialized_parts.iter().any(|part| {
                part.get("type").and_then(Value::as_str) == Some("userInterruption")
                    && part.get("content").and_then(Value::as_str)
                        == Some(REASONING_LOOP_RECOVERY_USER_TEXT)
                    && part.get("source").and_then(Value::as_str)
                        == Some(REASONING_LOOP_GUARD_SOURCE)
            }),
            "rematerialize must rebuild userInterruption: {rematerialized_parts:?}"
        );
        assert!(
            rematerialized_parts.iter().any(|part| {
                part.get("type").and_then(Value::as_str) == Some("text")
                    && part.get("text").and_then(Value::as_str)
                        == Some("Recovered after reasoning loop")
            }),
            "rematerialize must fold message content when stream deltas were not durable: {rematerialized_parts:?}"
        );
    }

    #[tokio::test]
    async fn remote_sidecar_chat_stream_reasoning_loop_fails_after_max_recoveries() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "exhaust recoveries",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);

        let response = remote_sidecar_chat_stream(
            State(state.clone()),
            Json(json!({
                "chatId": "chat-1",
                "queuedUserMessageId": "msg-user-1",
                "visibleAssistantMessageId": "msg-assistant-1",
                "modelId": "model-1",
                "providerId": "provider-1",
            })),
        )
        .await
        .expect("SSE response");

        let broker_state = state.clone();
        let max_recoveries = MAX_REASONING_LOOP_RECOVERIES_PER_RUN;
        let broker = tokio::spawn(async move {
            // MAX recoveries + 1 looping turns: recover 3 times, fail on 4th.
            for turn in 0..=max_recoveries {
                let request = loop {
                    let envelope = broker_rx.recv().await.expect("looping broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let id = request.id.clone().expect("request id");
                let pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&id)
                    .cloned()
                    .expect("pending response channel");
                let reasoning_period =
                    "Inspect the premise, compare the evidence, and restart the same analysis. ";
                for _ in 0..24 {
                    if pending
                        .send(ControlEnvelope {
                            version: 1,
                            message_type: "stream".to_string(),
                            id: Some(id.clone()),
                            method: None,
                            payload: json!({
                                "kind": "reasoningDelta",
                                "delta": reasoning_period,
                            }),
                            timestamp: None,
                        })
                        .is_err()
                    {
                        break;
                    }
                }
                loop {
                    let envelope = broker_rx.recv().await.expect("cancel");
                    if envelope.message_type == "cancel" {
                        assert_eq!(envelope.id.as_deref(), Some(id.as_str()));
                        break;
                    }
                }
                let _ = turn;
            }
        });

        let bytes = tokio::time::timeout(
            Duration::from_secs(8),
            axum::body::to_bytes(response.into_response().into_body(), usize::MAX),
        )
        .await
        .expect("max recovery SSE body should finish")
        .expect("SSE bytes");
        broker.await.expect("broker task");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        let guidance_count = text.matches("\"type\":\"guidanceApplied\"").count();
        assert_eq!(guidance_count, MAX_REASONING_LOOP_RECOVERIES_PER_RUN);
        assert!(text.contains("\"type\":\"error\""));
        assert!(text.contains("repeated reasoning loop"));
        assert!(text.contains("\"type\":\"streamEnd\""));
        assert!(!text.contains("\"type\":\"complete\""));

        let database = WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant message lookup")
            .expect("assistant message");
        let metadata =
            serde_json::from_str::<Value>(&assistant.metadata_json).expect("assistant metadata");
        let parts = metadata
            .get("parts")
            .and_then(Value::as_array)
            .expect("final partial parts");
        assert!(
            parts.iter().any(|part| {
                part.get("type").and_then(Value::as_str) == Some("userInterruption")
            }),
            "exhausted recoveries must keep interruption parts: {parts:?}"
        );
        assert!(
            parts.iter().any(|part| {
                part.get("type").and_then(Value::as_str) == Some("reasoning")
                    && part
                        .get("text")
                        .and_then(Value::as_str)
                        .is_some_and(|value| !value.is_empty())
            }),
            "exhausted recoveries must keep partial reasoning: {parts:?}"
        );
        let user = database
            .message("msg-user-1")
            .expect("user lookup")
            .expect("user message");
        let user_meta: Value = serde_json::from_str(&user.metadata_json).expect("user metadata");
        assert!(
            user_meta.get("queuedRun").is_none(),
            "failed recovery should clear queuedRun"
        );
    }

    #[tokio::test]
    async fn remote_sidecar_chat_stream_reasoning_loop_recovery_then_tool_stays_on_same_assistant()
    {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        fs::write(
            workspace.path().join("Cargo.toml"),
            "[package]\nname = \"fixture\"\n",
        )
        .expect("write tool fixture");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "loop then tool",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "queued",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        database
            .insert_message(NewMessage {
                id: "msg-assistant-1",
                chat_id: "chat-1",
                role: "assistant",
                content: "",
                sequence: 1,
                metadata_json: Some(r#"{"streamingState":"streaming"}"#),
            })
            .expect("insert assistant placeholder");
        drop(database);
        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);

        let response = remote_sidecar_chat_stream(
            State(state.clone()),
            Json(json!({
                "chatId": "chat-1",
                "queuedUserMessageId": "msg-user-1",
                "visibleAssistantMessageId": "msg-assistant-1",
                "modelId": "model-1",
                "providerId": "provider-1",
            })),
        )
        .await
        .expect("SSE response");

        let broker_state = state.clone();
        let broker =
            tokio::spawn(async move {
                // Turn 1: loop → cancel → recovery.
                let first_request = loop {
                    let envelope = broker_rx.recv().await.expect("first broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let first_id = first_request.id.clone().expect("first request id");
                let first_pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&first_id)
                    .cloned()
                    .expect("first pending");
                let reasoning_period =
                    "Inspect the premise, compare the evidence, and restart the same analysis. ";
                for _ in 0..24 {
                    if first_pending
                        .send(ControlEnvelope {
                            version: 1,
                            message_type: "stream".to_string(),
                            id: Some(first_id.clone()),
                            method: None,
                            payload: json!({
                                "kind": "reasoningDelta",
                                "delta": reasoning_period,
                            }),
                            timestamp: None,
                        })
                        .is_err()
                    {
                        break;
                    }
                }
                loop {
                    let envelope = broker_rx.recv().await.expect("first cancel");
                    if envelope.message_type == "cancel" {
                        assert_eq!(envelope.id.as_deref(), Some(first_id.as_str()));
                        break;
                    }
                }

                // Turn 2: after recovery, request a tool call on the same assistant message.
                let second_request = loop {
                    let envelope = broker_rx.recv().await.expect("second broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let second_messages = second_request.payload["request"]["messages"]
                    .as_array()
                    .expect("second messages");
                assert!(
                    second_messages.iter().any(|message| {
                        message["role"] == "user"
                            && message.get("content").and_then(Value::as_str).is_some_and(
                                |content| content.contains(REASONING_LOOP_RECOVERY_USER_TEXT),
                            )
                    }),
                    "tool turn must still include recovery user: {second_messages:?}"
                );
                let second_id = second_request.id.expect("second request id");
                let second_pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&second_id)
                    .cloned()
                    .expect("second pending");
                second_pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "response".to_string(),
                        id: Some(second_id.clone()),
                        method: None,
                        payload: json!({
                            "usage": { "inputTokens": 4, "outputTokens": 2 },
                            "toolCalls": [{
                                "callId": "call-after-recovery",
                                "name": "read_file",
                                "arguments": {
                                    "path": "Cargo.toml",
                                    "startLine": null,
                                    "endLine": null,
                                    "timeoutMs": null
                                }
                            }],
                        }),
                        timestamp: None,
                    })
                    .expect("send tool response");

                // Turn 3: tool result follow-up.
                let third_request = loop {
                    let envelope = broker_rx.recv().await.expect("third broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                assert!(
                    third_request.payload["request"]["messages"]
                        .as_array()
                        .expect("third messages")
                        .iter()
                        .any(|message| message["role"] == "tool"),
                    "third turn must include tool result"
                );
                let third_id = third_request.id.expect("third request id");
                let third_pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&third_id)
                    .cloned()
                    .expect("third pending");
                third_pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "stream".to_string(),
                        id: Some(third_id.clone()),
                        method: None,
                        payload: json!({
                            "kind": "textDelta",
                            "delta": "tool done after recovery",
                        }),
                        timestamp: None,
                    })
                    .expect("send final text");
                third_pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "response".to_string(),
                        id: Some(third_id),
                        method: None,
                        payload: json!({
                            "usage": { "inputTokens": 5, "outputTokens": 2 },
                            "toolCalls": [],
                        }),
                        timestamp: None,
                    })
                    .expect("send final response");
            });

        let bytes = tokio::time::timeout(
            Duration::from_secs(5),
            axum::body::to_bytes(response.into_response().into_body(), usize::MAX),
        )
        .await
        .expect("recovery+tool SSE body should finish")
        .expect("SSE bytes");
        broker.await.expect("broker task");
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 SSE");
        assert!(text.contains("\"type\":\"guidanceApplied\""));
        assert!(text.contains("\"type\":\"toolCall\""));
        assert!(text.contains("\"type\":\"toolResult\""));
        assert!(text.contains("\"type\":\"complete\""));
        assert!(text.contains("tool done after recovery"));
        assert!(!text.contains("\"type\":\"error\""));
        // Tool events must bind to the original assistant message id.
        assert!(text.contains("\"assistantMessageId\":\"msg-assistant-1\""));
        assert!(text.contains("call-after-recovery"));

        let database = WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        let tool_calls = database
            .tool_calls_for_message("msg-assistant-1")
            .expect("tool calls for assistant");
        assert_eq!(tool_calls.len(), 1);
        assert_eq!(tool_calls[0].id, "call-after-recovery");
        assert_eq!(tool_calls[0].tool_name, "read_file");
        let assistant = database
            .message("msg-assistant-1")
            .expect("assistant lookup")
            .expect("assistant");
        assert!(assistant.content.contains("tool done after recovery"));
        let metadata =
            serde_json::from_str::<Value>(&assistant.metadata_json).expect("assistant metadata");
        let parts = metadata
            .get("parts")
            .and_then(Value::as_array)
            .expect("parts");
        let interruption_idx = parts
            .iter()
            .position(|part| part.get("type").and_then(Value::as_str) == Some("userInterruption"));
        let tool_part_idx = parts.iter().position(|part| {
            part.get("type").and_then(Value::as_str) == Some("toolCall")
                && remote_tool_call_part_id(part) == Some("call-after-recovery")
        });
        let final_text_idx = parts.iter().position(|part| {
            part.get("type").and_then(Value::as_str) == Some("text")
                && part
                    .get("text")
                    .and_then(Value::as_str)
                    .is_some_and(|value| value.contains("tool done after recovery"))
        });
        assert!(
            interruption_idx.is_some(),
            "parts keep interruption before tool: {parts:?}"
        );
        assert!(
            tool_part_idx.is_some(),
            "complete must persist toolCall in ordered parts: {parts:?}"
        );
        assert!(
            final_text_idx.is_some(),
            "parts keep final text after tool: {parts:?}"
        );
        assert!(
            interruption_idx.unwrap() < tool_part_idx.unwrap()
                && tool_part_idx.unwrap() < final_text_idx.unwrap(),
            "expected interruption → toolCall → final text order, got {parts:?}"
        );

        // Next-run prompt rebuild must replay tools even when parts already exist
        // (not only the no-parts fallback path).
        let history = remote_sidecar_chat_messages_for_request(
            &database,
            "chat-1",
            Some("msg-assistant-next"),
            &std::collections::HashSet::new(),
        )
        .expect("history for next request");
        assert!(
            history.messages.iter().any(|message| {
                message.role == NeutralChatRole::User
                    && message.content.contains(REASONING_LOOP_RECOVERY_USER_TEXT)
            }),
            "next-run history must keep recovery user: {:?}",
            history.messages
        );
        assert!(
            history.messages.iter().any(|message| {
                message.role == NeutralChatRole::Assistant
                    && message
                        .tool_calls
                        .iter()
                        .any(|tool_call| tool_call.call_id == "call-after-recovery")
            }),
            "next-run history must keep tool call: {:?}",
            history.messages
        );
        assert!(
            history.messages.iter().any(|message| {
                message.role == NeutralChatRole::Tool
                    && message.tool_call_id.as_deref() == Some("call-after-recovery")
            }),
            "next-run history must keep tool result: {:?}",
            history.messages
        );
    }

    #[tokio::test]
    async fn remote_sidecar_llm_turn_uses_streamed_tool_call_when_response_omits_it() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        database
            .insert_message(NewMessage {
                id: "msg-user-1",
                chat_id: "chat-1",
                role: "user",
                content: "hello",
                sequence: 0,
                metadata_json: Some(
                    &json!({
                        "queuedRun": {
                            "status": "running",
                            "userMessageId": "msg-user-1",
                            "assistantMessageId": "msg-assistant-1",
                            "runId": "remote-run-1",
                        }
                    })
                    .to_string(),
                ),
            })
            .expect("insert user message");
        database
            .insert_message(NewMessage {
                id: "msg-assistant-1",
                chat_id: "chat-1",
                role: "assistant",
                content: "",
                sequence: 1,
                metadata_json: Some("{}"),
            })
            .expect("insert assistant placeholder");
        let (state, mut broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let run_stream = remote_sidecar_insert_active_run_stream(
            &state,
            "remote-run-1".to_string(),
            "chat-1".to_string(),
        );

        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let request = loop {
                let envelope = broker_rx.recv().await.expect("broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            let id = request.id.clone().expect("request id");
            let pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&id)
                .cloned()
                .expect("pending response channel");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "toolCall",
                        "toolCall": {
                            "callId": "call-1",
                            "name": "read_file",
                            "arguments": { "path": "Cargo.toml", "startLine": null, "endLine": null }
                        }
                    }),
                    timestamp: None,
                })
                .expect("send streamed tool call");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(id),
                    method: None,
                    payload: json!({
                        "providerId": "provider-current",
                        "usage": { "inputTokens": 4, "outputTokens": 2 },
                        "toolCalls": []
                    }),
                    timestamp: None,
                })
                .expect("send response without tool calls");
        });

        let mut text = String::new();
        let mut reasoning = String::new();
        let mut run_metrics = RemoteSidecarRunMetrics::new();
        let mut sequence = 0_i64;
        let outcome = remote_sidecar_run_broker_llm_turn(
            &state,
            &run_stream,
            "broker-request-1",
            json!({ "providerId": "provider-legacy", "modelId": "model-1" }),
            "remote-run-1",
            "chat-1",
            "msg-assistant-1",
            "msg-user-1",
            "provider-legacy",
            "model-1",
            &mut text,
            &mut reasoning,
            &mut run_metrics,
            &mut sequence,
            &[],
            &[],
            0,
            0,
        )
        .await
        .expect("llm turn should succeed");
        let (result, resolved_provider_id) = match outcome {
            RemoteSidecarBrokerLlmTurnOutcome::Completed {
                tool_calls: Some(tool_calls),
                resolved_provider_id,
                turn_input_tokens: _,
            } => (tool_calls, resolved_provider_id),
            other => panic!("expected tool followup completion, got {other:?}"),
        };
        broker.await.expect("broker task");

        assert_eq!(resolved_provider_id, "provider-current");
        let audit = database
            .llm_request("broker-request-1")
            .expect("sidecar audit lookup")
            .expect("sidecar audit exists");
        assert_eq!(audit.provider_id, "provider-current");
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].call_id, "call-1");
        assert_eq!(result[0].name, "read_file");
        assert_eq!(run_metrics.usage.input_tokens, Some(4));
        assert_eq!(run_metrics.usage.output_tokens, Some(2));
        assert!(run_metrics.first_token_latency_ms.is_some());
        // Recording pending tool calls / SSE toolCall events is the outer tool loop's job.
        assert!(
            database
                .tool_calls_for_message("msg-assistant-1")
                .expect("tool calls")
                .is_empty()
        );
    }

