    #[tokio::test]
    async fn remote_sidecar_context_compression_summary_aggregates_text_without_chat_metrics() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");
        let (state, mut broker_rx) = test_sidecar_state(workspace.path().display().to_string(), 1);
        let run_stream = RemoteActiveRunStream::new("chat-1".to_string());
        let broker_state = state.clone();
        let broker = tokio::spawn(async move {
            let request = loop {
                let envelope = broker_rx.recv().await.expect("broker request");
                if envelope.message_type == "request" {
                    break envelope;
                }
            };
            assert_eq!(request.method.as_deref(), Some("llm.stream"));
            assert_eq!(
                request.payload.get("requestKind").and_then(Value::as_str),
                Some("contextCompression")
            );
            let request_body = request
                .payload
                .get("request")
                .cloned()
                .expect("compression request body");
            let tools = request_body
                .get("tools")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            assert!(tools.is_empty());
            assert!(
                request_body
                    .get("thinking_level")
                    .map(|value| value.is_null())
                    .unwrap_or(true)
            );
            assert_eq!(
                request_body
                    .get("max_output_tokens")
                    .and_then(Value::as_u64),
                Some(2048)
            );
            let id = request.id.clone().expect("request id");
            let pending = broker_state
                .broker_pending
                .lock()
                .await
                .get(&id)
                .cloned()
                .expect("pending response channel");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "route",
                        "providerId": "provider-current",
                        "modelId": "model-1",
                    }),
                    timestamp: None,
                })
                .expect("send route confirmation");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "textDelta",
                        "delta": "User wants "
                    }),
                    timestamp: None,
                })
                .expect("send text delta");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "reasoningDelta",
                        "delta": "should not surface"
                    }),
                    timestamp: None,
                })
                .expect("send reasoning delta");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "stream".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "kind": "usageDelta",
                        "usage": { "inputTokens": 12, "outputTokens": 4 }
                    }),
                    timestamp: None,
                })
                .expect("send usage");
            pending
                .send(ControlEnvelope {
                    version: 1,
                    message_type: "response".to_string(),
                    id: Some(id.clone()),
                    method: None,
                    payload: json!({
                        "llmRequestId": id,
                        "text": "User wants remote compression.",
                        "usage": { "inputTokens": 12, "outputTokens": 4 },
                        "toolCalls": []
                    }),
                    timestamp: None,
                })
                .expect("send response");
        });

        let outcome = remote_sidecar_run_broker_context_compression_summary(
            &state,
            Some(&run_stream),
            "workspace",
            "chat-1",
            "remote-run-1",
            "msg-user-1",
            "msg-assistant-1",
            "provider-legacy",
            "model-1",
            128_000,
            &[neutral_text_message(
                NeutralChatRole::User,
                "goal: compress earlier turns".to_string(),
            )],
        )
        .await;
        broker.await.expect("broker task");

        match outcome {
            RemoteSidecarContextCompressionOutcome::Succeeded {
                summary,
                request_id,
                usage,
                provider_id,
            } => {
                // Stream deltas take precedence over response text when non-empty.
                assert_eq!(summary, "User wants");
                assert!(!request_id.is_empty());
                assert_eq!(usage.input_tokens, Some(12));
                assert_eq!(usage.output_tokens, Some(4));
                assert_eq!(provider_id, "provider-current");
            }
            other => panic!("expected succeeded summary, got {other:?}"),
        }

        // Compression must not record assistant-facing SSE deltas.
        assert!(run_stream.snapshot_after(0).is_empty());

        let rows = database
            .llm_request_audit_rows(LlmRequestAuditFilters {
                chat_id: Some("chat-1"),
                ..LlmRequestAuditFilters::default()
            })
            .expect("rows");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].request_kind, "contextCompression");
        assert_eq!(rows[0].final_state, "succeeded");
        // Sidecar mirror audit never stores provider_request_v1 wire dumps.
        let full = database
            .llm_request(&rows[0].id)
            .expect("full request")
            .expect("row");
        assert_eq!(full.provider_id, "provider-current");
        assert!(full.request_body_json.is_none());
        assert!(!crate::prompt::context_compression_summary_has_benefit(
            "User wants",
            1
        ));
        assert!(crate::prompt::context_compression_summary_has_benefit(
            "short", 10_000
        ));
    }

    #[tokio::test]
    async fn remote_sidecar_context_compression_summary_rejects_empty_and_tool_calls() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");

        // Empty text
        {
            let (state, mut broker_rx) =
                test_sidecar_state(workspace.path().display().to_string(), 1);
            let broker_state = state.clone();
            let broker = tokio::spawn(async move {
                let request = loop {
                    let envelope = broker_rx.recv().await.expect("broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let id = request.id.clone().expect("request id");
                let pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&id)
                    .cloned()
                    .expect("pending");
                pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "response".to_string(),
                        id: Some(id),
                        method: None,
                        payload: json!({
                            "text": "   ",
                            "usage": { "inputTokens": 1, "outputTokens": 0 },
                            "toolCalls": []
                        }),
                        timestamp: None,
                    })
                    .expect("send empty response");
            });
            let outcome = remote_sidecar_run_broker_context_compression_summary(
                &state,
                None,
                "workspace",
                "chat-1",
                "remote-run-empty",
                "msg-user-1",
                "msg-assistant-1",
                "provider-1",
                "model-1",
                128_000,
                &[neutral_text_message(
                    NeutralChatRole::User,
                    "source".to_string(),
                )],
            )
            .await;
            broker.await.expect("broker");
            match outcome {
                RemoteSidecarContextCompressionOutcome::Failed { message } => {
                    assert!(message.contains("empty text"));
                }
                other => panic!("expected failed empty summary, got {other:?}"),
            }
        }

        // Tool call
        {
            let (state, mut broker_rx) =
                test_sidecar_state(workspace.path().display().to_string(), 1);
            let broker_state = state.clone();
            let broker = tokio::spawn(async move {
                let request = loop {
                    let envelope = broker_rx.recv().await.expect("broker request");
                    if envelope.message_type == "request" {
                        break envelope;
                    }
                };
                let id = request.id.clone().expect("request id");
                let pending = broker_state
                    .broker_pending
                    .lock()
                    .await
                    .get(&id)
                    .cloned()
                    .expect("pending");
                pending
                    .send(ControlEnvelope {
                        version: 1,
                        message_type: "response".to_string(),
                        id: Some(id),
                        method: None,
                        payload: json!({
                            "text": "should not count",
                            "toolCalls": [{
                                "callId": "call-1",
                                "name": "read_file",
                                "arguments": { "path": "a" }
                            }]
                        }),
                        timestamp: None,
                    })
                    .expect("send tool response");
            });
            let outcome = remote_sidecar_run_broker_context_compression_summary(
                &state,
                None,
                "workspace",
                "chat-1",
                "remote-run-tools",
                "msg-user-1",
                "msg-assistant-1",
                "provider-1",
                "model-1",
                128_000,
                &[neutral_text_message(
                    NeutralChatRole::User,
                    "source".to_string(),
                )],
            )
            .await;
            broker.await.expect("broker");
            match outcome {
                RemoteSidecarContextCompressionOutcome::Failed { message } => {
                    assert!(message.contains("unsupported tool"));
                }
                other => panic!("expected failed tool summary, got {other:?}"),
            }
        }

        let rows = database
            .llm_request_audit_rows(LlmRequestAuditFilters {
                chat_id: Some("chat-1"),
                ..LlmRequestAuditFilters::default()
            })
            .expect("rows");
        assert_eq!(rows.len(), 2);
        assert!(
            rows.iter()
                .all(|row| row.request_kind == "contextCompression" && row.final_state == "failed")
        );
    }

    #[test]
    fn remote_sidecar_context_compression_failure_messages_are_distinct() {
        assert!(
            remote_sidecar_context_compression_failure_message(
                RemoteSidecarContextCompressionFailureKind::SummaryGeneration,
                "timeout",
            )
            .contains("summary generation failed")
        );
        assert!(
            remote_sidecar_context_compression_failure_message(
                RemoteSidecarContextCompressionFailureKind::NoBenefit,
                "",
            )
            .contains("no token savings")
        );
        assert!(
            remote_sidecar_context_compression_failure_message(
                RemoteSidecarContextCompressionFailureKind::StillOverBudget,
                "required",
            )
            .contains("still exceeds the model input budget")
        );
    }

    #[tokio::test]
    async fn remote_sidecar_ensure_compression_persists_llm_snapshot_via_broker() {
        let workspace = tempfile::tempdir().expect("workspace tempdir");
        let mut database =
            WorkspaceDatabase::open_or_create(workspace.path()).expect("workspace db");
        database
            .insert_chat_with_metadata("chat-1", "Remote chat", "{}")
            .expect("insert chat");

        let (state, broker_rx) =
            test_sidecar_state(workspace.path().to_string_lossy().to_string(), 1);
        let mut broker_rx = test_sidecar_broker_with_tool_discovery(state.clone(), broker_rx);
        let mut config =
            foco_store::config::GlobalConfig::first_run(workspace.path().to_path_buf());
        config.hooks = serde_json::from_value(json!({
            "auditEnabled": true,
            "PreCompact": [{
                "hooks": [{
                    "type": "command",
                    "command": "tee pre-compact-input.json >/dev/null; printf '%s' '{\"decision\":\"allow\",\"additionalContext\":\"pre remote context\",\"systemMessage\":\"pre compact ran\"}'"
                }, {
                    "type": "command",
                    "command": "printf '%s' 'pre compact warning' >&2; exit 1"
                }]
            }],
            "PostCompact": [{
                "hooks": [{
                    "type": "command",
                    "command": "tee post-compact-input.json >/dev/null; printf '%s' '{\"hookSpecificOutput\":{\"permissionDecision\":\"deny\",\"permissionDecisionReason\":\"post refusal does not rollback\"},\"additionalContext\":\"post remote context\"}'"
                }]
            }]
        }))
        .expect("compression hook config");
        // Prefer real model window for checkpoint budget so the mock single-request path stays
        // under budget; pack/trigger still use the injected tiny context_window below.
        config.models.push(foco_store::config::ModelSettings {
            id: "model-1".to_string(),
            display_name: "Model 1".to_string(),
            enabled: true,
            provider_ids: vec!["provider-1".to_string()],
            active_provider_id: Some("provider-1".to_string()),
            thinking_level: None,
            system_prompt_name: String::new(),
            metadata_key: None,
            metadata_source_url: None,
            metadata_refreshed_at: None,
            limits: Some(foco_store::config::ModelLimits {
                context_window: 128_000,
                max_output_tokens: 4096,
            }),
            input_modalities: Vec::new(),
            output_modalities: Vec::new(),
        });
        let bundle = build_sidecar_runtime_config_bundle(workspace.path(), &config, 1)
            .expect("runtime bundle");
        *state.runtime_config.lock().expect("runtime config") = Some(bundle);
        let broker_state = state.clone();
        let run_stream = RemoteActiveRunStream::new("chat-1".to_string());
        let mut messages = vec![
            neutral_text_message(NeutralChatRole::User, "old-history-0 ".repeat(400)),
            neutral_text_message(NeutralChatRole::Assistant, "old-history-1 ".repeat(400)),
            neutral_text_message(NeutralChatRole::User, "old-history-2 ".repeat(400)),
            neutral_text_message(NeutralChatRole::Assistant, "old-history-3 ".repeat(400)),
            neutral_text_message(NeutralChatRole::User, "current turn".to_string()),
        ];
        let mut runtime_tool_state = RemoteSidecarRuntimeToolState {
            message_source_sequences: vec![Some(0), Some(1), Some(2), Some(3), Some(4)],
            message_context_sources: vec![
                PromptContextSource::StoredMessage { sequence: 0 },
                PromptContextSource::StoredMessage { sequence: 1 },
                PromptContextSource::StoredMessage { sequence: 2 },
                PromptContextSource::StoredMessage { sequence: 3 },
                PromptContextSource::CurrentUser { sequence: 4 },
            ],
            active_tool_start_index: messages.len(),
            next_runtime_tool_batch_index: 0,
            runtime_tool_state_compression_count: 0,
            context_budget: ContextBudget {
                context_window: 1_000,
                max_output_tokens: 0,
                system_prompt_tokens: 0,
                tool_schema_tokens: 0,
                safety_tokens: 0,
                available_message_tokens: 10_000,
            },
            compression_enabled: false,
            compression_snapshots: Vec::new(),
            last_chat_completion_input_tokens: None,
        };

        let compress_task = tokio::spawn({
            let state = state.clone();
            let run_stream = run_stream.clone();
            async move {
                runtime_tool_state
                    .ensure_compression_then_pack(
                        &mut messages,
                        &state,
                        &run_stream,
                        "workspace",
                        "chat-1",
                        "run-1",
                        "msg-user-1",
                        "msg-assistant-1",
                        "provider-1",
                        "model-1",
                        None,
                    )
                    .await
                    .map(|(packed, events)| (packed, events, messages, runtime_tool_state))
            }
        });

        let request = timeout(Duration::from_secs(2), broker_rx.recv())
            .await
            .expect("broker request")
            .expect("broker envelope");
        assert_eq!(request.method.as_deref(), Some("llm.stream"));
        assert_eq!(
            request.payload.get("requestKind").and_then(Value::as_str),
            Some("contextCompression")
        );
        let id = request.id.clone().expect("request id");
        let pending = broker_state
            .broker_pending
            .lock()
            .await
            .get(&id)
            .cloned()
            .expect("pending response channel");
        pending
            .send(ControlEnvelope {
                version: 1,
                message_type: "stream".to_string(),
                id: Some(id.clone()),
                method: None,
                payload: json!({
                    "kind": "textDelta",
                    "delta": "compact remote summary for continuation"
                }),
                timestamp: None,
            })
            .expect("stream delta");
        pending
            .send(ControlEnvelope {
                version: 1,
                message_type: "response".to_string(),
                id: Some(id),
                method: None,
                payload: json!({
                    "llmRequestId": "broker-ctx-1",
                    "text": "compact remote summary for continuation",
                    "toolCalls": [],
                    "usage": { "inputTokens": 100, "outputTokens": 20 }
                }),
                timestamp: None,
            })
            .expect("response");

        let (packed, events, messages_after, runtime_after) = compress_task
            .await
            .expect("join")
            .expect("ensure compression");
        let notifications = run_stream.take_hook_notifications();
        assert!(notifications.iter().any(|notification| {
            notification.event == "PreCompact" && notification.message == "pre compact ran"
        }));
        assert!(
            notifications.iter().any(|notification| {
                notification.event == "PreCompact"
                    && notification.level == "warning"
                    && notification.message.contains("pre compact warning")
            }),
            "notifications: {notifications:?}"
        );
        assert!(
            notifications.iter().any(|notification| {
                notification.event == "PostCompact"
                    && notification
                        .message
                        .contains("post refusal does not rollback")
            }),
            "notifications: {notifications:?}"
        );
        assert_eq!(
            messages_after.len(),
            runtime_after.message_source_sequences.len()
        );
        assert_eq!(
            messages_after.len(),
            runtime_after.message_context_sources.len()
        );
        assert_eq!(runtime_after.active_tool_start_index, messages_after.len());
        assert_eq!(
            runtime_after
                .message_context_sources
                .iter()
                .filter(|source| matches!(source, PromptContextSource::HookContext))
                .count(),
            2
        );
        assert!(
            events
                .iter()
                .any(|event| event.kind == CONTEXT_COMPRESSION_KIND_LLM && event.status == "start")
        );
        assert!(events.iter().any(|event| {
            event.kind == CONTEXT_COMPRESSION_KIND_LLM
                && event.status == "completed"
                && event.snapshot_id.is_some()
        }));
        assert!(packed.iter().any(|message| {
            message
                .content
                .contains("compact remote summary for continuation")
        }));
        assert!(packed.iter().any(|message| {
            message.content.contains("Hook Context")
                && message.content.contains("pre remote context")
        }));
        assert!(packed.iter().any(|message| {
            message.content.contains("Hook Context")
                && message.content.contains("post remote context")
        }));
        assert!(
            packed
                .iter()
                .all(|message| !message.content.contains("old-history-0"))
        );

        let snapshots = WorkspaceDatabase::open_or_create(workspace.path())
            .expect("reopen db")
            .context_compression_snapshots_for_chat("chat-1")
            .expect("snapshots");
        assert_eq!(snapshots.len(), 1);
        assert_eq!(snapshots[0].chat_id, "chat-1");
        assert_eq!(snapshots[0].run_id, "run-1");
        assert!(snapshots[0].summary.contains("compact remote summary"));
        let metadata: Value =
            serde_json::from_str(&snapshots[0].metadata_json).expect("metadata json");
        assert_eq!(metadata.get("kind").and_then(Value::as_str), Some("llm"));
        assert!(metadata.get("coveredSequences").is_some());
        assert!(metadata.get("contextUsage").is_some());
        assert!(metadata.get("triggerTokens").is_some());
        assert!(metadata.get("availableMessageTokens").is_some());

        let pre_input: Value = serde_json::from_str(
            &fs::read_to_string(workspace.path().join("pre-compact-input.json"))
                .expect("pre compact input"),
        )
        .expect("pre compact input json");
        assert_eq!(
            pre_input.get("cwd").and_then(Value::as_str),
            workspace.path().to_str()
        );
        assert_eq!(
            pre_input.pointer("/payload/kind").and_then(Value::as_str),
            Some(CONTEXT_COMPRESSION_KIND_LLM)
        );
        assert!(
            pre_input
                .pointer("/payload/coveredSequences")
                .and_then(Value::as_array)
                .is_some_and(|sequences| !sequences.is_empty())
        );
        assert!(
            pre_input
                .pointer("/payload/originalTokenCount")
                .and_then(Value::as_u64)
                .is_some()
        );
        assert!(
            pre_input
                .pointer("/payload/summaryTokenCount")
                .and_then(Value::as_u64)
                .is_some()
        );
        assert_eq!(
            pre_input
                .pointer("/payload/summary")
                .and_then(Value::as_str),
            Some("compact remote summary for continuation")
        );
        let post_input: Value = serde_json::from_str(
            &fs::read_to_string(workspace.path().join("post-compact-input.json"))
                .expect("post compact input"),
        )
        .expect("post compact input json");
        assert_eq!(
            post_input
                .pointer("/payload/snapshotId")
                .and_then(Value::as_str),
            Some(snapshots[0].id.as_str())
        );
        let hook_runs = WorkspaceDatabase::open_or_create(workspace.path())
            .expect("reopen db for hook runs")
            .hook_runs(10)
            .expect("hook runs");
        assert_eq!(hook_runs.len(), 3);
        assert_eq!(
            hook_runs
                .iter()
                .filter(|run| run.event == "PreCompact")
                .count(),
            2
        );
        assert!(hook_runs.iter().any(|run| run.event == "PostCompact"));
    }

